1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"syscall"
12		"time"
13	)
14	
15	// 包裹状态。
16	const (
17		// statusInStation 表示包裹当前在某站点（已收件、已完成交接或回执失败回到出发站）。
18		statusInStation = "在站"
19		// statusDelivering 表示包裹已随某个配送批次出站，正在配送中。
20		statusDelivering = "配送中"
21		// statusSigned 表示包裹已签收（回执结果为签收）。
22		statusSigned = "已签收"
23		// statusFrozen 表示在站包裹因异常被冻结：站点不变，禁止交接、配送出站与整批退回。
24		statusFrozen = "异常冻结"
25	)
26	
27	// 回执结果。
28	const (
29		resultSigned = "签收"
30		resultFailed = "失败"
31	)
32	
33	// Event 是包裹轨迹中的一条记录，按提交顺序追加。
34	type Event struct {
35		Op         string    `json:"op"`                   // 收件 | 交接 | 退回 | 出站 | 回执 | 冻结 | 解除冻结 | 收回 | 续接 | 撤销回执
36		Station    string    `json:"station"`              // 与该操作有关的站点（退回时为退回目的站，即原交接源站；冻结/解除冻结为包裹所在站点；收回/续接/撤销回执为批次出发站）
37		Time       time.Time `json:"time"`                 // 发生时间
38		Request    string    `json:"request,omitempty"`    // 交接/退回/回执/收回/续接/撤销请求号（收件、出站记录为空）
39		From       string    `json:"from,omitempty"`       // 退回源站（原交接目的站，仅退回记录有）
40		Reason     string    `json:"reason,omitempty"`     // 退回原因（仅退回记录有）、回执失败原因（仅失败回执有）、冻结原因（仅冻结记录有）、中止原因（仅收回记录有）、续接原因（仅续接记录有）或撤销原因（仅撤销回执记录有）
41		RefRequest string    `json:"refRequest,omitempty"` // 被退回的原交接请求号（仅退回记录有）或被撤销的原回执请求号（仅撤销回执记录有）
42		Batch      string    `json:"batch,omitempty"`      // 配送批次号（仅出站、回执、收回、续接、撤销回执记录有；续接时为新批次号）
43		FromBatch  string    `json:"fromBatch,omitempty"`  // 续接原批次号（仅续接记录有）
44		Courier    string    `json:"courier,omitempty"`    // 配送员（仅出站、续接记录有；续接时为新配送员）
45		Result     string    `json:"result,omitempty"`     // 回执结果：签收 | 失败（仅回执记录有）
46		// Incident 为冻结/解除冻结记录的异常单号；解除冻结时另外用 Request 存解除请求号、Note 存处理说明。
47		Incident string `json:"incident,omitempty"`
48		Note     string `json:"note,omitempty"`
49	}
50	
51	// Parcel 是一件包裹的台账信息。
52	type Parcel struct {
53		ID         string    `json:"id"`
54		Station    string    `json:"station"`    // 当前归属站点
55		Status     string    `json:"status"`     // 当前状态
56		Registered time.Time `json:"registered"` // 收件时间
57		Trail      []Event   `json:"trail"`      // 完整轨迹，按提交顺序排列
58	}
59	
60	// HandoffResult 记录一次成功交接，用于请求号去重与结果重放。
61	type HandoffResult struct {
62		Request    string    `json:"request"`
63		From       string    `json:"from"`
64		To         string    `json:"to"`
65		Parcels    []string  `json:"parcels"` // 按首次提交时给出的顺序保存
66		Time       time.Time `json:"time"`
67		ReturnedBy string    `json:"returnedBy,omitempty"` // 已成功退回该交接的退回请求号（未退回为空）
68	}
69	
70	// ReturnResult 记录一次成功的整批退回，用于退回请求号去重与结果重放。
71	type ReturnResult struct {
72		Request string    `json:"request"` // 退回请求号
73		Handoff string    `json:"handoff"` // 被退回的原交接请求号
74		From    string    `json:"from"`    // 退回源站（原交接目的站）
75		To      string    `json:"to"`      // 退回目的站（原交接源站）
76		Reason  string    `json:"reason"`
77		Parcels []string  `json:"parcels"` // 原交接批次，按原交接保存的顺序
78		Time    time.Time `json:"time"`
79	}
80	
81	// ReceiptEntry 是批次内一件包裹的当前回执记录（被新回执取代的已撤销条目由
82	// 台账级 Receipts 结果表与撤销记录共同保留）。
83	type ReceiptEntry struct {
84		Request string    `json:"request"`          // 回执请求号
85		Result  string    `json:"result"`           // 签收 | 失败
86		Reason  string    `json:"reason,omitempty"` // 失败原因（仅失败回执有）
87		Time    time.Time `json:"time"`
88		// RevokedBy 为撤销该回执的撤销请求号（未撤销为空）；撤销后该条不再计入有效回执。
89		RevokedBy string `json:"revokedBy,omitempty"`
90	}
91	
92	// BatchResult 记录一次成功的配送批次出站，用于批次号去重、结果重放与批次查询。
93	// 成员按首次提交时给出的顺序保存，保存后不可修改；批次完成后批次号也不能复用。
94	type BatchResult struct {
95		Batch    string                   `json:"batch"`
96		Station  string                   `json:"station"`  // 出发站
97		Courier  string                   `json:"courier"`  // 配送员
98		Parcels  []string                 `json:"parcels"`  // 批次成员，按首次提交顺序
99		Time     time.Time                `json:"time"`     // 出站时间
100		Receipts map[string]*ReceiptEntry `json:"receipts"` // 逐件回执，按包裹编号索引（未回执的包裹不在其中）
101		// AbortedBy 为中止该批次的中止请求号（未中止为空）；中止永久生效，批次不得复用。
102		AbortedBy string `json:"abortedBy,omitempty"`
103		// TransferredBy 为把该批次关闭为“已转交”的续接请求号（未转交为空）；
104		// 转交永久生效，与中止互斥，批次不得复用。
105		TransferredBy string `json:"transferredBy,omitempty"`
106		// RelayedFrom 与 RelayRequest 仅对续接创建的新批次有效：分别记录来源批次号
107		// 与创建本批次的续接请求号（普通出站批次为空）。
108		RelayedFrom  string `json:"relayedFrom,omitempty"`
109		RelayRequest string `json:"relayRequest,omitempty"`
110	}
111	
112	// Effective 返回批次当前有效（未撤销）的回执数量。
113	func (b *BatchResult) Effective() int {
114		n := 0
115		for _, e := range b.Receipts {
116			if e != nil && e.RevokedBy == "" {
117				n++
118			}
119		}
120		return n
121	}
122	
123	// Done 报告批次是否已完成（全部成员均有未撤销的有效回执）。
124	func (b *BatchResult) Done() bool { return b.Effective() == len(b.Parcels) }
125	
126	// ReceiptResult 记录一次成功的逐件回执，用于回执请求号去重与结果重放。
127	// 回执结果永久保留：即使之后被撤销，回执请求号也不删除、不释放。
128	type ReceiptResult struct {
129		Request string    `json:"request"` // 回执请求号
130		Batch   string    `json:"batch"`   // 所属配送批次号
131		Parcel  string    `json:"parcel"`  // 包裹编号
132		Result  string    `json:"result"`  // 签收 | 失败
133		Reason  string    `json:"reason,omitempty"`
134		Time    time.Time `json:"time"`
135		// RevokedBy 为撤销该回执的撤销请求号（未撤销为空）；每条回执只能被撤销一次。
136		RevokedBy string `json:"revokedBy,omitempty"`
137	}
138	
139	// FreezeResult 记录一次成功的异常冻结，用于异常单号去重与结果重放。
140	// 异常单号标识一次异常，解除后也不能复用；失败的首次冻结不占用异常单号。
141	type FreezeResult struct {
142		Incident string    `json:"incident"` // 异常单号
143		Parcel   string    `json:"parcel"`   // 被冻结的包裹编号
144		Station  string    `json:"station"`  // 冻结时包裹所在站点（冻结与解除期间均不变）
145		Reason   string    `json:"reason"`   // 清理后的冻结原因
146		Time     time.Time `json:"time"`     // 冻结时间
147		// ReleasedBy 为解除该异常单的解除请求号（未解除为空）；解除后异常单永久保留、不得复用。
148		ReleasedBy string `json:"releasedBy,omitempty"`
149	}
150	
151	// UnfreezeResult 记录一次成功的解除冻结，用于解除请求号去重与结果重放。
152	// 解除请求号独立去重，可与异常单号、包裹号及其他业务编号同名；失败的首次解除不占用请求号。
153	type UnfreezeResult struct {
154		Request  string    `json:"request"`  // 解除请求号
155		Incident string    `json:"incident"` // 被解除的异常单号
156		Parcel   string    `json:"parcel"`   // 对应包裹编号
157		Note     string    `json:"note"`     // 清理后的处理说明
158		Time     time.Time `json:"time"`     // 解除时间
159	}
160	
161	// AbortResult 记录一次成功的配送批次中止，用于中止请求号去重与结果重放。
162	// 中止表示配送员已将该批次全部尚未回执的包裹实物收回出发站：批次永久关闭，
163	// 原成员顺序、配送员与出站时间保留不变，已回执成员及其回执完全保留。
164	// 中止请求号独立去重，可与批次号、包裹号及其他业务编号同名；失败的首次中止不占用请求号。
165	type AbortResult struct {
166		Request string    `json:"request"` // 中止请求号
167		Batch   string    `json:"batch"`   // 被中止的配送批次号
168		Station string    `json:"station"` // 出发站（收回目的站，取自原批次）
169		Reason  string    `json:"reason"`  // 清理后的中止原因
170		Parcels []string  `json:"parcels"` // 首次收回的未回执包裹，按原批次成员顺序
171		Time    time.Time `json:"time"`    // 中止时间
172	}
173	
174	// TransferResult 记录一次成功的配送途中整批续接，用于续接请求号去重与结果重放。
175	// 续接表示原配送员把原批次全部尚未回执的包裹在配送途中交给另一配送员：
176	// 新批次按原顺序接纳全部未回执件继续配送，包裹保持“配送中”及原站点，
177	// 原批次永久关闭为“已转交”。续接请求号独立去重，可与批次号、包裹号及其他
178	// 业务编号同名；失败的首次续接不占用请求号。
179	type TransferResult struct {
180		Request     string    `json:"request"`     // 续接请求号
181		FromBatch   string    `json:"fromBatch"`   // 原批次号
182		ToBatch     string    `json:"toBatch"`     // 新批次号
183		Station     string    `json:"station"`     // 出发站（沿用原批次）
184		FromCourier string    `json:"fromCourier"` // 原配送员（取自原批次）
185		ToCourier   string    `json:"toCourier"`   // 新配送员
186		Reason      string    `json:"reason"`      // 清理后的续接原因
187		Parcels     []string  `json:"parcels"`     // 首次转交集合（原批次未回执成员，按原成员顺序）
188		Time        time.Time `json:"time"`        // 接手时间
189	}
190	
191	// RevokeResult 记录一次成功的误录回执撤销，用于撤销请求号去重与结果重放。
192	// 撤销只更正台账：经核实包裹实际仍由原配送员配送，撤销错误的签收或失败登记，
193	// 不收回实物。原回执结果与轨迹永久保留并标记已撤销，回执请求号不删除也不释放。
194	// 撤销请求号独立去重，可与批次号、包裹号、回执请求号及其他业务编号同名；
195	// 失败的首次撤销不占用请求号。
196	type RevokeResult struct {
197		Request string    `json:"request"` // 撤销请求号
198		Receipt string    `json:"receipt"` // 被撤销的原回执请求号
199		Batch   string    `json:"batch"`   // 所属配送批次号（取自原回执，不可另选）
200		Parcel  string    `json:"parcel"`  // 包裹编号（取自原回执，不可另选）
201		Reason  string    `json:"reason"`  // 清理后的撤销原因
202		Time    time.Time `json:"time"`    // 撤销时间
203	}
204	
205	// ledgerFile 是本地数据文件的磁盘结构。
206	type ledgerFile struct {
207		Version   int                        `json:"version"`
208		Parcels   map[string]*Parcel         `json:"parcels"`
209		Handoffs  map[string]*HandoffResult  `json:"handoffs"`
210		Returns   map[string]*ReturnResult   `json:"returns"`
211		Batches   map[string]*BatchResult    `json:"batches"`
212		Receipts  map[string]*ReceiptResult  `json:"receipts"`
213		Freezes   map[string]*FreezeResult   `json:"freezes"`   // 以异常单号为键（含已解除的异常单，永久保留）
214		Unfreezes map[string]*UnfreezeResult `json:"unfreezes"` // 以解除请求号为键
215		Aborts    map[string]*AbortResult    `json:"aborts"`    // 以中止请求号为键
216		Transfers map[string]*TransferResult `json:"transfers"` // 以续接请求号为键
217		Revokes   map[string]*RevokeResult   `json:"revokes"`   // 以撤销请求号为键
218	}
219	
220	// Store 是一个数据文件对应的包裹站点交接台账。
221	type Store struct {
222		path string
223		data ledgerFile
224	}
225	
226	var (
227		// ErrCorrupt 表示数据文件已存在但内容损坏，不得当作空库继续读写。
228		ErrCorrupt = errors.New("数据文件已损坏")
229		// ErrNotFound 表示包裹编号在台账中不存在。
230		ErrNotFound = errors.New("包裹不存在")
231	)
232	
233	// Open 打开（或在文件不存在时建立）一个本地台账。
234	// 文件不存在时仅初始化内存结构，真正建文件发生在首次成功保存时。
235	func Open(path string) (*Store, error) {
236		s := &Store{path: path}
237		raw, err := os.ReadFile(path)
238		if err != nil {
239			if os.IsNotExist(err) {
240				s.data = ledgerFile{Version: 1, Parcels: map[string]*Parcel{}, Handoffs: map[string]*HandoffResult{},
241					Returns: map[string]*ReturnResult{}, Batches: map[string]*BatchResult{}, Receipts: map[string]*ReceiptResult{},
242					Freezes: map[string]*FreezeResult{}, Unfreezes: map[string]*UnfreezeResult{}, Aborts: map[string]*AbortResult{},
243					Transfers: map[string]*TransferResult{}, Revokes: map[string]*RevokeResult{}}
244				return s, nil
245			}
246			return nil, fmt.Errorf("读取数据文件失败: %w", err)
247		}
248		if len(bytes.TrimSpace(raw)) == 0 {
249			return nil, fmt.Errorf("%w: 文件为空", ErrCorrupt)
250		}
251		if err := json.Unmarshal(raw, &s.data); err != nil {
252			return nil, fmt.Errorf("%w: %v", ErrCorrupt, err)
253		}
254		if s.data.Version != 1 || s.data.Parcels == nil || s.data.Handoffs == nil {
255			return nil, fmt.Errorf("%w: 缺少必要字段或版本不受支持", ErrCorrupt)
256		}
257		// 早期版本的数据文件没有 returns/batches/receipts/freeze/abort/revoke 相关字段：按空表处理，无需手工修改。
258		if s.data.Returns == nil {
259			s.data.Returns = map[string]*ReturnResult{}
260		}
261		if s.data.Batches == nil {
262			s.data.Batches = map[string]*BatchResult{}
263		}
264		if s.data.Receipts == nil {
265			s.data.Receipts = map[string]*ReceiptResult{}
266		}
267		if s.data.Freezes == nil {
268			s.data.Freezes = map[string]*FreezeResult{}
269		}
270		if s.data.Unfreezes == nil {
271			s.data.Unfreezes = map[string]*UnfreezeResult{}
272		}
273		if s.data.Aborts == nil {
274			s.data.Aborts = map[string]*AbortResult{}
275		}
276		if s.data.Transfers == nil {
277			s.data.Transfers = map[string]*TransferResult{}
278		}
279		if s.data.Revokes == nil {
280			s.data.Revokes = map[string]*RevokeResult{}
281		}
282		for _, b := range s.data.Batches {
283			if b != nil && b.Receipts == nil {
284				b.Receipts = map[string]*ReceiptEntry{}
285			}
286		}
287		if err := s.data.validate(); err != nil {
288			return nil, err
289		}
290		return s, nil
291	}
292	
293	// validate 校验载入内容内部自洽，防止损坏数据被当作有效台账继续使用。
294	func (l *ledgerFile) validate() error {
295		for id, p := range l.Parcels {
296			if p == nil || id != p.ID || p.Station == "" || p.Status == "" || len(p.Trail) == 0 {
297				return fmt.Errorf("%w: 包裹 %q 记录不完整", ErrCorrupt, id)
298			}
299			switch p.Status {
300			case statusInStation, statusDelivering, statusSigned, statusFrozen:
301			default:
302				return fmt.Errorf("%w: 包裹 %q 的状态 %q 不受支持", ErrCorrupt, id, p.Status)
303			}
304			for i, e := range p.Trail {
305				if e.Op == "" || e.Station == "" || e.Time.IsZero() {
306					return fmt.Errorf("%w: 包裹 %q 第 %d 条轨迹缺少操作、站点或发生时间", ErrCorrupt, id, i+1)
307				}
308				if e.Op == "退回" {
309					if e.Request == "" || e.Reason == "" || e.From == "" {
310						return fmt.Errorf("%w: 包裹 %q 第 %d 条退回轨迹缺少退回请求号、源站或原因", ErrCorrupt, id, i+1)
311					}
312					if _, ok := l.Handoffs[e.RefRequest]; !ok {
313						return fmt.Errorf("%w: 包裹 %q 第 %d 条退回轨迹引用了不存在的原交接 %q", ErrCorrupt, id, i+1, e.RefRequest)
314					}
315				}
316				if e.Op == "出站" {
317					if e.Batch == "" || e.Courier == "" {
318						return fmt.Errorf("%w: 包裹 %q 第 %d 条出站轨迹缺少批次号或配送员", ErrCorrupt, id, i+1)
319					}
320					if _, ok := l.Batches[e.Batch]; !ok {
321						return fmt.Errorf("%w: 包裹 %q 第 %d 条出站轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
322					}
323				}
324				if e.Op == "回执" {
325					if e.Batch == "" || e.Request == "" || (e.Result != resultSigned && e.Result != resultFailed) {
326						return fmt.Errorf("%w: 包裹 %q 第 %d 条回执轨迹缺少批次号、请求号或结果无效", ErrCorrupt, id, i+1)
327					}
328					if e.Result == resultFailed && e.Reason == "" {
329						return fmt.Errorf("%w: 包裹 %q 第 %d 条失败回执轨迹缺少原因", ErrCorrupt, id, i+1)
330					}
331					if _, ok := l.Batches[e.Batch]; !ok {
332						return fmt.Errorf("%w: 包裹 %q 第 %d 条回执轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
333					}
334				}
335				if e.Op == "撤销回执" {
336					if e.Batch == "" || e.Request == "" || e.RefRequest == "" || e.Reason == "" {
337						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹缺少批次号、撤销请求号、原回执请求号或原因", ErrCorrupt, id, i+1)
338					}
339					b, ok := l.Batches[e.Batch]
340					if !ok {
341						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹引用了不存在的批次 %q", ErrCorrupt, id, i+1, e.Batch)
342					}
343					if e.Station != b.Station {
344						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹的站点 %q 与批次 %q 出发站 %q 不一致",
345							ErrCorrupt, id, i+1, e.Station, e.Batch, b.Station)
346					}
347					rv, ok := l.Revokes[e.Request]
348					if !ok {
349						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹引用了不存在的撤销请求 %q", ErrCorrupt, id, i+1, e.Request)
350					}
351					if rv.Receipt != e.RefRequest || rv.Batch != e.Batch || rv.Parcel != id || rv.Reason != e.Reason || !rv.Time.Equal(e.Time) {
352						return fmt.Errorf("%w: 包裹 %q 第 %d 条撤销回执轨迹与撤销请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
353					}
354				}
355				if e.Op == "收回" {
356					if e.Batch == "" || e.Request == "" || e.Reason == "" {
357						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹缺少批次号、中止请求号或原因", ErrCorrupt, id, i+1)
358					}
359					a, ok := l.Aborts[e.Request]
360					if !ok {
361						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹引用了不存在的中止请求 %q", ErrCorrupt, id, i+1, e.Request)
362					}
363					if a.Batch != e.Batch || a.Station != e.Station || a.Reason != e.Reason || !a.Time.Equal(e.Time) {
364						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹与中止请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
365					}
366					inAbort := false
367					for _, pid := range a.Parcels {
368						if pid == id {
369							inAbort = true
370							break
371						}
372					}
373					if !inAbort {
374						return fmt.Errorf("%w: 包裹 %q 第 %d 条收回轨迹不在中止请求 %q 的收回集合中", ErrCorrupt, id, i+1, e.Request)
375					}
376				}
377				if e.Op == "续接" {
378					if e.Batch == "" || e.FromBatch == "" || e.Courier == "" || e.Request == "" || e.Reason == "" {
379						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹缺少新批次号、原批次号、新配送员、续接请求号或原因", ErrCorrupt, id, i+1)
380					}
381					t, ok := l.Transfers[e.Request]
382					if !ok {
383						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹引用了不存在的续接请求 %q", ErrCorrupt, id, i+1, e.Request)
384					}
385					if t.FromBatch != e.FromBatch || t.ToBatch != e.Batch || t.ToCourier != e.Courier ||
386						t.Station != e.Station || t.Reason != e.Reason || !t.Time.Equal(e.Time) {
387						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹与续接请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
388					}
389					inTransfer := false
390					for _, pid := range t.Parcels {
391						if pid == id {
392							inTransfer = true
393							break
394						}
395					}
396					if !inTransfer {
397						return fmt.Errorf("%w: 包裹 %q 第 %d 条续接轨迹不在续接请求 %q 的转交集合中", ErrCorrupt, id, i+1, e.Request)
398					}
399				}
400				if e.Op == "冻结" {
401					if e.Incident == "" || e.Reason == "" {
402						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结轨迹缺少异常单号或原因", ErrCorrupt, id, i+1)
403					}
404					f, ok := l.Freezes[e.Incident]
405					if !ok {
406						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结轨迹引用了不存在的异常单 %q", ErrCorrupt, id, i+1, e.Incident)
407					}
408					if f.Parcel != id || f.Reason != e.Reason || f.Station != e.Station || !f.Time.Equal(e.Time) {
409						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结轨迹与异常单 %q 记录不一致", ErrCorrupt, id, i+1, e.Incident)
410					}
411				}
412				if e.Op == "解除冻结" {
413					if e.Incident == "" || e.Request == "" || e.Note == "" {
414						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹缺少异常单号、解除请求号或处理说明", ErrCorrupt, id, i+1)
415					}
416					f, ok := l.Freezes[e.Incident]
417					if !ok {
418						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹引用了不存在的异常单 %q", ErrCorrupt, id, i+1, e.Incident)
419					}
420					if f.Parcel != id || f.Station != e.Station || f.ReleasedBy != e.Request {
421						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹与异常单 %q 不匹配", ErrCorrupt, id, i+1, e.Incident)
422					}
423					u, ok := l.Unfreezes[e.Request]
424					if !ok || u.Incident != e.Incident || u.Parcel != id || u.Note != e.Note || !u.Time.Equal(e.Time) {
425						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除冻结轨迹与解除请求 %q 记录不一致", ErrCorrupt, id, i+1, e.Request)
426					}
427				}
428			}
429		}
430		for req, h := range l.Handoffs {
431			if h == nil || req != h.Request || h.From == "" || h.To == "" || len(h.Parcels) == 0 {
432				return fmt.Errorf("%w: 请求号 %q 的交接结果不完整", ErrCorrupt, req)
433			}
434			for _, id := range h.Parcels {
435				if _, ok := l.Parcels[id]; !ok {
436					return fmt.Errorf("%w: 请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, id)
437				}
438			}
439			if h.ReturnedBy != "" {
440				r, ok := l.Returns[h.ReturnedBy]
441				if !ok || r.Handoff != req {
442					return fmt.Errorf("%w: 交接 %q 标记的退回请求号 %q 无法对应", ErrCorrupt, req, h.ReturnedBy)
443				}
444			}
445		}
446		for req, r := range l.Returns {
447			if r == nil || req != r.Request || r.Handoff == "" || r.From == "" || r.To == "" ||
448				r.Reason == "" || len(r.Parcels) == 0 || r.Time.IsZero() {
449				return fmt.Errorf("%w: 退回请求号 %q 的退回结果不完整", ErrCorrupt, req)
450			}
451			h, ok := l.Handoffs[r.Handoff]
452			if !ok {
453				return fmt.Errorf("%w: 退回请求号 %q 引用了不存在的原交接 %q", ErrCorrupt, req, r.Handoff)
454			}
455			if h.ReturnedBy != req || r.From != h.To || r.To != h.From || !sameSet(r.Parcels, h.Parcels) {
456				return fmt.Errorf("%w: 退回请求号 %q 与原交接 %q 的记录不一致", ErrCorrupt, req, r.Handoff)
457			}
458			for _, id := range r.Parcels {
459				if _, ok := l.Parcels[id]; !ok {
460					return fmt.Errorf("%w: 退回请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, id)
461				}
462			}
463		}
464		for id, b := range l.Batches {
465			if b == nil || id != b.Batch || b.Station == "" || b.Courier == "" || len(b.Parcels) == 0 || b.Time.IsZero() {
466				return fmt.Errorf("%w: 批次号 %q 的出站结果不完整", ErrCorrupt, id)
467			}
468			seen := make(map[string]bool, len(b.Parcels))
469			for _, pid := range b.Parcels {
470				if seen[pid] {
471					return fmt.Errorf("%w: 批次 %q 的成员 %q 重复", ErrCorrupt, id, pid)
472				}
473				seen[pid] = true
474				if _, ok := l.Parcels[pid]; !ok {
475					return fmt.Errorf("%w: 批次 %q 引用了不存在的包裹 %q", ErrCorrupt, id, pid)
476				}
477			}
478			for pid, e := range b.Receipts {
479				if e == nil || !seen[pid] || e.Request == "" || e.Time.IsZero() ||
480					(e.Result != resultSigned && e.Result != resultFailed) ||
481					(e.Result == resultFailed && e.Reason == "") || (e.Result == resultSigned && e.Reason != "") {
482					return fmt.Errorf("%w: 批次 %q 中包裹 %q 的回执记录不完整", ErrCorrupt, id, pid)
483				}
484				rc, ok := l.Receipts[e.Request]
485				if !ok || rc.Batch != id || rc.Parcel != pid {
486					return fmt.Errorf("%w: 批次 %q 中包裹 %q 的回执请求号 %q 无法对应", ErrCorrupt, id, pid, e.Request)
487				}
488				if e.RevokedBy != rc.RevokedBy {
489					return fmt.Errorf("%w: 批次 %q 中包裹 %q 的回执条目与回执请求号 %q 的撤销标记不一致", ErrCorrupt, id, pid, e.Request)
490				}
491			}
492			if b.AbortedBy != "" {
493				a, ok := l.Aborts[b.AbortedBy]
494				if !ok || a.Batch != id {
495					return fmt.Errorf("%w: 批次 %q 标记的中止请求号 %q 无法对应", ErrCorrupt, id, b.AbortedBy)
496				}
497			}
498			if b.TransferredBy != "" {
499				if b.AbortedBy != "" {
500					return fmt.Errorf("%w: 批次 %q 不能同时标记中止与转交", ErrCorrupt, id)
501				}
502				t, ok := l.Transfers[b.TransferredBy]
503				if !ok || t.FromBatch != id {
504					return fmt.Errorf("%w: 批次 %q 标记的续接请求号 %q 无法对应", ErrCorrupt, id, b.TransferredBy)
505				}
506			}
507			if b.RelayedFrom != "" {
508				t, ok := l.Transfers[b.RelayRequest]
509				if !ok || t.ToBatch != id || t.FromBatch != b.RelayedFrom {
510					return fmt.Errorf("%w: 批次 %q 标记的续接来源（原批次=%q 续接请求号=%q）无法对应",
511						ErrCorrupt, id, b.RelayedFrom, b.RelayRequest)
512				}
513			} else if b.RelayRequest != "" {
514				return fmt.Errorf("%w: 批次 %q 标记了续接请求号 %q 但缺少来源批次", ErrCorrupt, id, b.RelayRequest)
515			}
516		}
517		for req, rc := range l.Receipts {
518			if rc == nil || req != rc.Request || rc.Batch == "" || rc.Parcel == "" || rc.Time.IsZero() ||
519				(rc.Result != resultSigned && rc.Result != resultFailed) ||
520				(rc.Result == resultFailed && rc.Reason == "") || (rc.Result == resultSigned && rc.Reason != "") {
521				return fmt.Errorf("%w: 回执请求号 %q 的回执结果不完整", ErrCorrupt, req)
522			}
523			b, ok := l.Batches[rc.Batch]
524			if !ok {
525				return fmt.Errorf("%w: 回执请求号 %q 引用了不存在的批次 %q", ErrCorrupt, req, rc.Batch)
526			}
527			// 每件包裹的当前回执条目一旦建立只会被新回执取代、不会删除，
528			// 因此该件在批次内必须始终有一条回执条目。
529			e, cur := b.Receipts[rc.Parcel]
530			if !cur {
531				return fmt.Errorf("%w: 回执请求号 %q 在批次 %q 中缺少包裹 %q 的回执条目", ErrCorrupt, req, rc.Batch, rc.Parcel)
532			}
533			if rc.RevokedBy == "" {
534				// 未撤销回执必须仍是该件在该批次的当前有效回执。
535				if e.Request != req || e.Result != rc.Result || e.Reason != rc.Reason || !e.Time.Equal(rc.Time) || e.RevokedBy != "" {
536					return fmt.Errorf("%w: 回执请求号 %q 与批次 %q 的回执记录不一致", ErrCorrupt, req, rc.Batch)
537				}
538				continue
539			}
540			// 已撤销回执：撤销关联必须存在且回指该回执。
541			rv, ok := l.Revokes[rc.RevokedBy]
542			if !ok || rv.Receipt != req {
543				return fmt.Errorf("%w: 回执请求号 %q 标记的撤销请求号 %q 无法对应", ErrCorrupt, req, rc.RevokedBy)
544			}
545			if e.Request == req {
546				// 该件之后未重新回执：批次内条目必须同内容并同样标记撤销。
547				if e.Result != rc.Result || e.Reason != rc.Reason || !e.Time.Equal(rc.Time) || e.RevokedBy != rc.RevokedBy {
548					return fmt.Errorf("%w: 回执请求号 %q 与批次 %q 的回执记录不一致", ErrCorrupt, req, rc.Batch)
549				}
550			}
551			// 该件之后已用新请求号重新回执：当前条目属于新回执，由其自身校验。
552		}
553		// 撤销：每条撤销必须对应一条已撤销回执，批次、包裹一致，且包裹轨迹中有
554		// 与该撤销请求一致的撤销回执记录；撤销关联缺失或不一致即损坏。
555		for req, rv := range l.Revokes {
556			if rv == nil || req != rv.Request || rv.Receipt == "" || rv.Batch == "" || rv.Parcel == "" ||
557				rv.Reason == "" || rv.Time.IsZero() {
558				return fmt.Errorf("%w: 撤销请求号 %q 的撤销结果不完整", ErrCorrupt, req)
559			}
560			rc, ok := l.Receipts[rv.Receipt]
561			if !ok {
562				return fmt.Errorf("%w: 撤销请求号 %q 引用了不存在的原回执 %q", ErrCorrupt, req, rv.Receipt)
563			}
564			if rc.RevokedBy != req {
565				return fmt.Errorf("%w: 撤销请求号 %q 与原回执 %q 的撤销标记不一致", ErrCorrupt, req, rv.Receipt)
566			}
567			if rc.Batch != rv.Batch || rc.Parcel != rv.Parcel {
568				return fmt.Errorf("%w: 撤销请求号 %q 的批次或包裹与原回执 %q 不一致", ErrCorrupt, req, rv.Receipt)
569			}
570			p, ok := l.Parcels[rv.Parcel]
571			if !ok {
572				return fmt.Errorf("%w: 撤销请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, rv.Parcel)
573			}
574			found := false
575			for _, e := range p.Trail {
576				if e.Op == "撤销回执" && e.Request == req {
577					found = true
578					break
579				}
580			}
581			if !found {
582				return fmt.Errorf("%w: 撤销请求号 %q 的包裹 %q 缺少对应的撤销回执轨迹", ErrCorrupt, req, rv.Parcel)
583			}
584		}
585		// 中止：收回集合必须恰为原批次的未回执成员（按原成员顺序，已撤销回执不计入
586		// 有效回执），且每件收回包裹的轨迹中都有与该中止请求一致的收回记录；
587		// 中止记录与收回轨迹不一致即损坏。
588		for req, a := range l.Aborts {
589			if a == nil || req != a.Request || a.Batch == "" || a.Station == "" || a.Reason == "" ||
590				len(a.Parcels) == 0 || a.Time.IsZero() {
591				return fmt.Errorf("%w: 中止请求号 %q 的中止结果不完整", ErrCorrupt, req)
592			}
593			b, ok := l.Batches[a.Batch]
594			if !ok {
595				return fmt.Errorf("%w: 中止请求号 %q 引用了不存在的批次 %q", ErrCorrupt, req, a.Batch)
596			}
597			if b.AbortedBy != req {
598				return fmt.Errorf("%w: 中止请求号 %q 与批次 %q 的中止标记不一致", ErrCorrupt, req, a.Batch)
599			}
600			if a.Station != b.Station {
601				return fmt.Errorf("%w: 中止请求号 %q 的站点 %q 与批次 %q 出发站 %q 不一致", ErrCorrupt, req, a.Station, a.Batch, b.Station)
602			}
603			expect := make([]string, 0, len(b.Parcels))
604			for _, pid := range b.Parcels {
605				if e, done := b.Receipts[pid]; !done || e.RevokedBy != "" {
606					expect = append(expect, pid)
607				}
608			}
609			if len(expect) != len(a.Parcels) {
610				return fmt.Errorf("%w: 中止请求号 %q 的收回集合与批次 %q 的未回执成员不一致", ErrCorrupt, req, a.Batch)
611			}
612			for i := range expect {
613				if expect[i] != a.Parcels[i] {
614					return fmt.Errorf("%w: 中止请求号 %q 的收回集合与批次 %q 的未回执成员不一致", ErrCorrupt, req, a.Batch)
615				}
616			}
617			for _, pid := range a.Parcels {
618				p, ok := l.Parcels[pid]
619				if !ok {
620					return fmt.Errorf("%w: 中止请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, pid)
621				}
622				found := false
623				for _, e := range p.Trail {
624					if e.Op == "收回" && e.Request == req {
625						found = true
626						break
627					}
628				}
629				if !found {
630					return fmt.Errorf("%w: 中止请求号 %q 的收回包裹 %q 缺少对应的收回轨迹", ErrCorrupt, req, pid)
631				}
632			}
633		}
634		// 续接：转交集合必须恰为原批次的未回执成员（按原成员顺序），新批次必须由该续接
635		// 创建且成员、站点、配送员、接手时间与之一致；每件转交包裹的轨迹中都有与该
636		// 续接请求一致的续接记录；续接记录与批次及轨迹不一致即损坏。
637		for req, t := range l.Transfers {
638			if t == nil || req != t.Request || t.FromBatch == "" || t.ToBatch == "" || t.Station == "" ||
639				t.FromCourier == "" || t.ToCourier == "" || t.FromCourier == t.ToCourier ||
640				t.Reason == "" || len(t.Parcels) == 0 || t.Time.IsZero() {
641				return fmt.Errorf("%w: 续接请求号 %q 的续接结果不完整", ErrCorrupt, req)
642			}
643			fb, ok := l.Batches[t.FromBatch]
644			if !ok {
645				return fmt.Errorf("%w: 续接请求号 %q 引用了不存在的原批次 %q", ErrCorrupt, req, t.FromBatch)
646			}
647			if fb.TransferredBy != req {
648				return fmt.Errorf("%w: 续接请求号 %q 与原批次 %q 的转交标记不一致", ErrCorrupt, req, t.FromBatch)
649			}
650			if fb.Station != t.Station || fb.Courier != t.FromCourier {
651				return fmt.Errorf("%w: 续接请求号 %q 的站点或原配送员与原批次 %q 不一致", ErrCorrupt, req, t.FromBatch)
652			}
653			nb, ok := l.Batches[t.ToBatch]
654			if !ok {
655				return fmt.Errorf("%w: 续接请求号 %q 引用了不存在的新批次 %q", ErrCorrupt, req, t.ToBatch)
656			}
657			if nb.RelayedFrom != t.FromBatch || nb.RelayRequest != req {
658				return fmt.Errorf("%w: 续接请求号 %q 与新批次 %q 的来源标记不一致", ErrCorrupt, req, t.ToBatch)
659			}
660			if nb.Station != t.Station || nb.Courier != t.ToCourier || !nb.Time.Equal(t.Time) {
661				return fmt.Errorf("%w: 续接请求号 %q 与新批次 %q 的站点、配送员或接手时间不一致", ErrCorrupt, req, t.ToBatch)
662			}
663			expect := make([]string, 0, len(fb.Parcels))
664			for _, pid := range fb.Parcels {
665				if e, done := fb.Receipts[pid]; !done || e.RevokedBy != "" {
666					expect = append(expect, pid)
667				}
668			}
669			if !sameOrder(expect, t.Parcels) || !sameOrder(t.Parcels, nb.Parcels) {
670				return fmt.Errorf("%w: 续接请求号 %q 的转交集合与原批次 %q 的未回执成员或新批次 %q 的成员不一致",
671					ErrCorrupt, req, t.FromBatch, t.ToBatch)
672			}
673			for _, pid := range t.Parcels {
674				p, ok := l.Parcels[pid]
675				if !ok {
676					return fmt.Errorf("%w: 续接请求号 %q 引用了不存在的包裹 %q", ErrCorrupt, req, pid)
677				}
678				found := false
679				for _, e := range p.Trail {
680					if e.Op == "续接" && e.Request == req {
681						found = true
682						break
683					}
684				}
685				if !found {
686					return fmt.Errorf("%w: 续接请求号 %q 的转交包裹 %q 缺少对应的续接轨迹", ErrCorrupt, req, pid)
687				}
688			}
689		}
690		// 冻结/解除冻结：先遍历轨迹核对冻结与解除必须成对出现、顺序正确，
691		// 再核对两张结果表与包裹当前状态的对应关系。
692		openIncident := make(map[string]string) // 包裹 -> 当前未解除的异常单号（由轨迹推导）
693		for id, p := range l.Parcels {
694			var open string
695			for i, e := range p.Trail {
696				switch e.Op {
697				case "冻结":
698					if open != "" {
699						return fmt.Errorf("%w: 包裹 %q 第 %d 条冻结时异常单 %q 尚未解除，一件包裹同时只能有一张未解除异常单",
700							ErrCorrupt, id, i+1, open)
701					}
702					open = e.Incident
703				case "解除冻结":
704					if open != e.Incident {
705						return fmt.Errorf("%w: 包裹 %q 第 %d 条解除的异常单 %q 与当前冻结 %q 不匹配",
706							ErrCorrupt, id, i+1, e.Incident, open)
707					}
708					open = ""
709				}
710			}
711			if p.Status == statusFrozen && open == "" {
712				return fmt.Errorf("%w: 包裹 %q 当前为异常冻结，但轨迹中没有未解除的冻结记录", ErrCorrupt, id)
713			}
714			if p.Status != statusFrozen && open != "" {
715				return fmt.Errorf("%w: 包裹 %q 当前状态为 %q，但异常单 %q 尚未解除", ErrCorrupt, id, p.Status, open)
716			}
717			if open != "" {
718				openIncident[id] = open
719			}
720		}
721		for no, f := range l.Freezes {
722			if f == nil || no != f.Incident || f.Parcel == "" || f.Station == "" || f.Reason == "" || f.Time.IsZero() {
723				return fmt.Errorf("%w: 异常单号 %q 的冻结结果不完整", ErrCorrupt, no)
724			}
725			p, ok := l.Parcels[f.Parcel]
726			if !ok {
727				return fmt.Errorf("%w: 异常单 %q 引用了不存在的包裹 %q", ErrCorrupt, no, f.Parcel)
728			}
729			if f.ReleasedBy == "" && p.Station != f.Station {
730				return fmt.Errorf("%w: 异常单 %q 记录的站点 %q 与包裹 %q 当前站点 %q 不一致",
731					ErrCorrupt, no, f.Station, f.Parcel, p.Station)
732			}
733			if f.ReleasedBy != "" {
734				u, ok := l.Unfreezes[f.ReleasedBy]
735				if !ok || u.Incident != no || u.Parcel != f.Parcel {
736					return fmt.Errorf("%w: 异常单 %q 标记的解除请求号 %q 无法对应", ErrCorrupt, no, f.ReleasedBy)
737				}
738			}
739		}
740		activeByParcel := make(map[string]string)
741		for req, u := range l.Unfreezes {
742			if u == nil || req != u.Request || u.Incident == "" || u.Parcel == "" || u.Note == "" || u.Time.IsZero() {
743				return fmt.Errorf("%w: 解除请求号 %q 的解除结果不完整", ErrCorrupt, req)
744			}
745			f, ok := l.Freezes[u.Incident]
746			if !ok {
747				return fmt.Errorf("%w: 解除请求号 %q 引用了不存在的异常单 %q", ErrCorrupt, req, u.Incident)
748			}
749			if f.Parcel != u.Parcel {
750				return fmt.Errorf("%w: 解除请求号 %q 与异常单 %q 对应的包裹不一致", ErrCorrupt, req, u.Incident)
751			}
752			if f.ReleasedBy != req {
753				return fmt.Errorf("%w: 解除请求号 %q 与异常单 %q 的解除标记不一致", ErrCorrupt, req, u.Incident)
754			}
755		}
756		for no, f := range l.Freezes {
757			if f.ReleasedBy != "" {
758				continue
759			}
760			if other, dup := activeByParcel[f.Parcel]; dup {
761				return fmt.Errorf("%w: 包裹 %q 同时存在两张未解除异常单 %q 与 %q", ErrCorrupt, f.Parcel, other, no)
762			}
763			activeByParcel[f.Parcel] = no
764			if openIncident[f.Parcel] != no {
765				return fmt.Errorf("%w: 包裹 %q 当前冻结对应的异常单应为 %q，与未解除异常单 %q 不匹配",
766					ErrCorrupt, f.Parcel, openIncident[f.Parcel], no)
767			}
768			if p := l.Parcels[f.Parcel]; p.Status != statusFrozen {
769				return fmt.Errorf("%w: 异常单 %q 未解除，但包裹 %q 当前状态为 %q", ErrCorrupt, no, f.Parcel, p.Status)
770			}
771		}
772		return nil
773	}
