775	// coordinationPath 返回数据文件对应的协调文件（锁文件）路径。
776	// 相对、绝对及含 .、.. 的写法先归一到同一绝对路径，已存在的符号链接也被解析，
777	// 确保同一台账的不同路径写法共用同一把锁；首次创建不存在的台账同样适用。
778	func coordinationPath(path string) (string, error) {
779		abs, err := filepath.Abs(path)
780		if err != nil {
781			return "", fmt.Errorf("解析数据文件路径失败: %w", err)
782		}
783		if resolved, err := filepath.EvalSymlinks(abs); err == nil {
784			abs = resolved
785		} else if dir, derr := filepath.EvalSymlinks(filepath.Dir(abs)); derr == nil {
786			abs = filepath.Join(dir, filepath.Base(abs))
787		}
788		return abs + ".lock", nil
789	}
790	
791	// OpenForUpdate 在进程间排他协调下打开台账，供会改写台账的命令使用：
792	// 先取得该台账的锁（其他终端正在作业时等待其完成），再在锁内读取最新已提交
793	// 数据；调用方随后完成的受理、去重与整次保存都在最新数据上进行，并行效果
794	// 等同于某个逐次执行顺序。返回的 release 必须在本次命令结束时调用（无论成败）。
795	// 锁由操作系统随文件描述符管理，持有者进程被强制终止时自动释放，
796	// 无需人工删除协调文件即可继续作业。
797	func OpenForUpdate(path string) (s *Store, release func(), err error) {
798		lockPath, err := coordinationPath(path)
799		if err != nil {
800			return nil, nil, err
801		}
802		if err := os.MkdirAll(filepath.Dir(lockPath), 0o755); err != nil {
803			return nil, nil, fmt.Errorf("准备协调文件失败: %w", err)
804		}
805		lock, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
806		if err != nil {
807			return nil, nil, fmt.Errorf("打开协调文件失败: %w", err)
808		}
809		if err := syscall.Flock(int(lock.Fd()), syscall.LOCK_EX); err != nil {
810			_ = lock.Close()
811			return nil, nil, fmt.Errorf("等待台账协调锁失败: %w", err)
812		}
813		release = func() {
814			_ = syscall.Flock(int(lock.Fd()), syscall.LOCK_UN)
815			_ = lock.Close()
816		}
817		s, err = Open(path)
818		if err != nil {
819			release()
820			return nil, nil, err
821		}
822		return s, release, nil
823	}
