870	// Handoff 提交一次多件包裹的站点交接。
871	//
872	// 首次提交：所有包裹必须已登记且当前归属源站点，否则整次失败、不作任何改动；
873	// 全部满足时一起改归目的站点并各追加一条交接记录，作为一个整体保存。
874	// 相同请求号且业务内容（源、目的、包裹集合，与顺序无关）相同：直接返回首次结果，
875	// 返回值 replayed 为 true；相同请求号但业务内容不同：报冲突，已有结果不变。
876	func (s *Store) Handoff(request, from, to string, parcels []string, now time.Time) (result *HandoffResult, replayed bool, err error) {
877		if saved, ok := s.data.Handoffs[request]; ok {
878			if saved.From == from && saved.To == to && sameSet(saved.Parcels, parcels) {
879				return saved, true, nil
880			}
881			return nil, false, fmt.Errorf("请求号 %q 已用于一次不同的交接（源=%q 目的=%q），内容冲突", request, saved.From, saved.To)
882		}
883	
884		// 首次提交：先做全部校验，任何一件不满足都整体失败。
885		for _, id := range parcels {
886			p, ok := s.data.Parcels[id]
887			if !ok {
888				return nil, false, fmt.Errorf("交接失败：包裹 %q 未登记，整次交接未执行", id)
889			}
890			if p.Station != from {
891				return nil, false, fmt.Errorf("交接失败：包裹 %q 当前归属 %q，不属于源站点 %q，整次交接未执行", id, p.Station, from)
892			}
893			if inc := activeFreeze(p); inc != "" {
894				return nil, false, fmt.Errorf("交接失败：包裹 %q 已被异常单 %q 冻结，冻结期间整批交接拒绝，整次交接未执行", id, inc)
895			}
896			if p.Status != statusInStation {
897				return nil, false, fmt.Errorf("交接失败：包裹 %q 当前状态为 %q，不是在站，整次交接未执行", id, p.Status)
898			}
899		}
900	
901		res := &HandoffResult{
902			Request: request,
903			From:    from,
904			To:      to,
905			Parcels: append([]string(nil), parcels...),
906			Time:    now,
907		}
908		s.data.Handoffs[request] = res
909	
910		// 记录旧值，落盘失败时整体回滚。
911		prev := make(map[string]struct {
912			station string
913			trail   []Event
914		}, len(parcels))
915		for _, id := range parcels {
916			p := s.data.Parcels[id]
917			prev[id] = struct {
918				station string
919				trail   []Event
920			}{p.Station, append([]Event(nil), p.Trail...)}
921			p.Station = to
922			p.Status = statusInStation
923			p.Trail = append(p.Trail, Event{
924				Op:      "交接",
925				Station: to,
926				Request: request,
927				Time:    now,
928			})
929		}
930	
931		if err := s.save(); err != nil {
932			delete(s.data.Handoffs, request)
933			for id, old := range prev {
934				p := s.data.Parcels[id]
935				p.Station = old.station
936				p.Trail = old.trail
937			}
938			return nil, false, err
939		}
940		return res, false, nil
941	}
