943	// Return 按原交接整批退回：实物送回该交接的源站点，批次与站点取自原交接结果。
944	//
945	// 首次退回：原交接必须存在且尚未成功退回；批次中每件包裹必须仍归属原交接目的站、
946	// 状态为在站，且最后一条流转记录就是该原交接（请求重放不产生新流转，不影响判定）。
947	// 任一条件不满足则整批拒绝，不作任何改动。全部满足时整批改归原交接源站（仍为在站），
948	// 每件按批次顺序追加一条退回记录，原收件、交接轨迹保留不变。
949	// 相同退回请求号且原交接、原因相同：直接返回首次结果，replayed 为 true，
950	// 即使包裹之后又被交接也不重新检查；请求号相同但原交接或原因不同：报冲突。
951	// 退回请求号与交接请求号分属独立去重范围，互不影响；失败的首次退回不占用请求号。
952	func (s *Store) Return(request, handoffReq, reason string, now time.Time) (result *ReturnResult, replayed bool, err error) {
953		if saved, ok := s.data.Returns[request]; ok {
954			if saved.Handoff == handoffReq && saved.Reason == reason {
955				return saved, true, nil
956			}
957			return nil, false, fmt.Errorf("退回请求号 %q 已用于一次不同的退回（原交接=%q 原因=%q），内容冲突",
958				request, saved.Handoff, saved.Reason)
959		}
960	
961		h, ok := s.data.Handoffs[handoffReq]
962		if !ok {
963			return nil, false, fmt.Errorf("退回失败：原交接请求号 %q 不存在", handoffReq)
964		}
965		if h.ReturnedBy != "" {
966			return nil, false, fmt.Errorf("退回失败：原交接 %q 已成功退回（退回请求号 %q），不能再次退回", handoffReq, h.ReturnedBy)
967		}
968	
969		// 先做全部校验，任何一件不满足都整批拒绝。
970		for _, id := range h.Parcels {
971			p, ok := s.data.Parcels[id]
972			if !ok {
973				return nil, false, fmt.Errorf("退回失败：包裹 %q 未登记，整批退回未执行", id)
974			}
975			if inc := activeFreeze(p); inc != "" {
976				return nil, false, fmt.Errorf("退回失败：包裹 %q 已被异常单 %q 冻结，冻结期间整批退回拒绝，整批退回未执行", id, inc)
977			}
978			if p.Station != h.To || p.Status != statusInStation {
979				return nil, false, fmt.Errorf("退回失败：包裹 %q 当前归属 %q、状态 %q，不在原交接目的站 %q 在站，整批退回未执行",
980					id, p.Station, p.Status, h.To)
981			}
982			last := lastFlowEvent(p.Trail)
983			if last.Op != "交接" || last.Request != handoffReq {
984				return nil, false, fmt.Errorf("退回失败：包裹 %q 在原交接 %q 之后又有新的流转，不能退回该交接，整批退回未执行",
985					id, handoffReq)
986			}
987		}
988	
989		res := &ReturnResult{
990			Request: request,
991			Handoff: handoffReq,
992			From:    h.To,
993			To:      h.From,
994			Reason:  reason,
995			Parcels: append([]string(nil), h.Parcels...),
996			Time:    now,
997		}
998		s.data.Returns[request] = res
999		h.ReturnedBy = request
1000	
1001		// 记录旧值，落盘失败时整体回滚。
1002		prev := make(map[string]struct {
1003			station string
1004			trail   []Event
1005		}, len(h.Parcels))
1006		for _, id := range h.Parcels {
1007			p := s.data.Parcels[id]
1008			prev[id] = struct {
1009				station string
1010				trail   []Event
1011			}{p.Station, append([]Event(nil), p.Trail...)}
1012			p.Station = h.From
1013			p.Status = statusInStation
1014			p.Trail = append(p.Trail, Event{
1015				Op:         "退回",
1016				Station:    h.From,
1017				From:       h.To,
1018				Request:    request,
1019				RefRequest: handoffReq,
1020				Reason:     reason,
1021				Time:       now,
1022			})
1023		}
1024	
1025		if err := s.save(); err != nil {
1026			delete(s.data.Returns, request)
1027			h.ReturnedBy = ""
1028			for id, old := range prev {
1029				p := s.data.Parcels[id]
1030				p.Station = old.station
1031				p.Trail = old.trail
1032			}
1033			return nil, false, err
1034		}
1035		return res, false, nil
1036	}
