1038	// Dispatch 提交一次配送批次出站。
1039	//
1040	// 首次出站：所有包裹必须已登记、当前归属出发站且状态为在站，否则整批拒绝、不作任何改动；
1041	// 全部满足时整批转为“配送中”（站点仍记出发站），每件追加一条含批次、配送员和时间的
1042	// 出站记录，批次成员按首次提交顺序保存且不可修改。批次号标识一次配送，完成后也不能复用：
1043	// 相同批次号且站点、配送员、包裹集合（与顺序无关）相同，直接返回首次结果，replayed 为 true；
1044	// 批次号相同但内容不同报冲突；失败的首次出站不占用批次号。
1045	func (s *Store) Dispatch(batch, station, courier string, parcels []string, now time.Time) (result *BatchResult, replayed bool, err error) {
1046		if saved, ok := s.data.Batches[batch]; ok {
1047			if saved.RelayedFrom != "" {
1048				return nil, false, fmt.Errorf("批次号 %q 已由续接 %q 创建（来源批次 %q），不能用于出站，内容冲突",
1049					batch, saved.RelayRequest, saved.RelayedFrom)
1050			}
1051			if saved.Station == station && saved.Courier == courier && sameSet(saved.Parcels, parcels) {
1052				return saved, true, nil
1053			}
1054			return nil, false, fmt.Errorf("批次号 %q 已用于一次不同的出站（出发站=%q 配送员=%q），内容冲突", batch, saved.Station, saved.Courier)
1055		}
1056	
1057		// 首次出站：先做全部校验，任何一件不满足都整批拒绝。
1058		for _, id := range parcels {
1059			p, ok := s.data.Parcels[id]
1060			if !ok {
1061				return nil, false, fmt.Errorf("出站失败：包裹 %q 未登记，整批出站未执行", id)
1062			}
1063			if p.Station != station {
1064				return nil, false, fmt.Errorf("出站失败：包裹 %q 当前归属 %q，不在出发站 %q，整批出站未执行", id, p.Station, station)
1065			}
1066			if inc := activeFreeze(p); inc != "" {
1067				return nil, false, fmt.Errorf("出站失败：包裹 %q 已被异常单 %q 冻结，冻结期间整批出站拒绝，整批出站未执行", id, inc)
1068			}
1069			if p.Status != statusInStation {
1070				return nil, false, fmt.Errorf("出站失败：包裹 %q 当前状态为 %q，不是在站，整批出站未执行", id, p.Status)
1071			}
1072		}
1073	
1074		res := &BatchResult{
1075			Batch:    batch,
1076			Station:  station,
1077			Courier:  courier,
1078			Parcels:  append([]string(nil), parcels...),
1079			Time:     now,
1080			Receipts: map[string]*ReceiptEntry{},
1081		}
1082		s.data.Batches[batch] = res
1083	
1084		// 记录旧值，落盘失败时整体回滚。
1085		prev := make(map[string]struct {
1086			status string
1087			trail  []Event
1088		}, len(parcels))
1089		for _, id := range parcels {
1090			p := s.data.Parcels[id]
1091			prev[id] = struct {
1092				status string
1093				trail  []Event
1094			}{p.Status, append([]Event(nil), p.Trail...)}
1095			p.Status = statusDelivering // 站点不变，仍记出发站
1096			p.Trail = append(p.Trail, Event{
1097				Op:      "出站",
1098				Station: station,
1099				Batch:   batch,
1100				Courier: courier,
1101				Time:    now,
1102			})
1103		}
1104	
1105		if err := s.save(); err != nil {
1106			delete(s.data.Batches, batch)
1107			for id, old := range prev {
1108				p := s.data.Parcels[id]
1109				p.Status = old.status
1110				p.Trail = old.trail
1111			}
1112			return nil, false, err
1113		}
1114		return res, false, nil
1115	}
1116	
1117	// Receipt 提交一件包裹在某个配送批次下的回执。
1118	//
1119	// 首次回执：批次必须存在，包裹必须属于该批次、在该批次没有未撤销的回执，且当前仍在该批次
1120	// 配送中；任一不满足则拒绝，不作任何改动。签收后状态为“已签收”；失败表示实物已回到
1121	// 出发站，恢复“在站”，可加入新的配送批次。两种结果都保留站点并追加一条含批次、结果、
1122	// 原因（失败时）、请求号和时间的回执记录；全部成员均有未撤销回执后批次自动完成。
1123	// 已撤销的回执不再占用该件的回执名额，可用新请求号重新回执（见 RevokeReceipt）。
1124	// 相同回执请求号且批次、包裹、结果、清理后的原因相同：直接返回首次结果，replayed 为
1125	// true，不重新检查当前状态，即使失败包裹已进入新批次或该回执已被撤销（重放不恢复回执，
1126	// 结果中可辨认已撤销）；请求号相同但内容不同报冲突。
1127	// 回执请求号与批次号、包裹编号、交接及退回请求号分属独立去重范围，允许同名；
1128	// 失败的首次回执不占用请求号。
1129	func (s *Store) Receipt(request, batch, parcel, result, reason string, now time.Time) (res *ReceiptResult, replayed bool, err error) {
1130		res, replayed, undo, err := s.applyReceipt(request, batch, parcel, result, reason, now)
1131		if err != nil || replayed {
1132			return res, replayed, err
1133		}
1134		if err := s.save(); err != nil {
1135			undo() // 落盘失败：回滚内存变更，保留原有有效数据
1136			return nil, false, err
1137		}
1138		return res, false, nil
1139	}
1140	
1141	// applyReceipt 在内存台账上校验并应用一条回执（不落盘），是 Receipt 与
1142	// ImportReceipts 共用的核心。全部校验通过后才会改动数据；返回的 undo 可在
1143	// 整体保存失败时撤销本次改动（重放或校验失败时 undo 为 nil）。
1144	func (s *Store) applyReceipt(request, batch, parcel, result, reason string, now time.Time) (res *ReceiptResult, replayed bool, undo func(), err error) {
1145		if saved, ok := s.data.Receipts[request]; ok {
1146			if saved.Batch == batch && saved.Parcel == parcel && saved.Result == result && saved.Reason == reason {
1147				return saved, true, nil, nil
1148			}
1149			return nil, false, nil, fmt.Errorf("回执请求号 %q 已用于一次不同的回执（批次=%q 包裹=%q 结果=%q），内容冲突",
1150				request, saved.Batch, saved.Parcel, saved.Result)
1151		}
1152	
1153		b, ok := s.data.Batches[batch]
1154		if !ok {
1155			return nil, false, nil, fmt.Errorf("回执失败：批次号 %q 不存在", batch)
1156		}
1157		member := false
1158		for _, id := range b.Parcels {
1159			if id == parcel {
1160				member = true
1161				break
1162			}
1163		}
1164		if !member {
1165			return nil, false, nil, fmt.Errorf("回执失败：包裹 %q 不属于批次 %q", parcel, batch)
1166		}
1167		if e, done := b.Receipts[parcel]; done && e.RevokedBy == "" {
1168			return nil, false, nil, fmt.Errorf("回执失败：包裹 %q 在批次 %q 中已回执，每件在一个批次只能有一条未撤销回执", parcel, batch)
1169		}
1170		p := s.data.Parcels[parcel] // 批次成员必已登记（载入校验保证）
1171		if p.Status != statusDelivering || currentBatch(p) != batch {
1172			return nil, false, nil, fmt.Errorf("回执失败：包裹 %q 当前状态为 %q，不在批次 %q 配送中", parcel, p.Status, batch)
1173		}
1174	
1175		res = &ReceiptResult{
1176			Request: request,
1177			Batch:   batch,
1178			Parcel:  parcel,
1179			Result:  result,
1180			Reason:  reason,
1181			Time:    now,
1182		}
1183		entry := &ReceiptEntry{Request: request, Result: result, Reason: reason, Time: now}
1184	
1185		// 记录旧值，undo 在整体落盘失败时回滚。
1186		oldStatus, oldStation := p.Status, p.Station
1187		oldTrailLen := len(p.Trail)
1188		oldEntry, hadEntry := b.Receipts[parcel] // 被取代的已撤销条目（若有）
1189	
1190		if result == resultSigned {
1191			p.Status = statusSigned // 站点保留不变
1192		} else {
1193			p.Status = statusInStation // 实物已回到出发站，可加入新的配送批次
1194			p.Station = b.Station
1195		}
1196		p.Trail = append(p.Trail, Event{
1197			Op:      "回执",
1198			Station: p.Station,
1199			Batch:   batch,
1200			Result:  result,
1201			Reason:  reason,
1202			Request: request,
1203			Time:    now,
1204		})
1205		b.Receipts[parcel] = entry
1206		s.data.Receipts[request] = res
1207	
1208		undo = func() {
1209			delete(s.data.Receipts, request)
1210			if hadEntry {
1211				b.Receipts[parcel] = oldEntry
1212			} else {
1213				delete(b.Receipts, parcel)
1214			}
1215			p.Status, p.Station = oldStatus, oldStation
1216			p.Trail = p.Trail[:oldTrailLen]
1217		}
1218		return res, false, undo, nil
1219	}
