1221	// ReceiptImportRecord 是回执整批导入文件中的一条记录（已清洗）。
1222	type ReceiptImportRecord struct {
1223		Request string // 回执请求号（与逐件 receipt 共用去重范围）
1224		Batch   string // 配送批次号
1225		Parcel  string // 包裹编号
1226		Result  string // 签收 | 失败
1227		Reason  string // 失败原因（失败时非空，签收时为空）
1228	}
1229	
1230	// ReceiptImportItem 是整批导入中一条记录的处理结果，按文件顺序排列。
1231	type ReceiptImportItem struct {
1232		Record   ReceiptImportRecord // 清洗后的记录内容
1233		Time     time.Time           // 发生时间（重放时为首次保存的时间）
1234		Replayed bool                // true 表示同内容历史重放，未产生新变更
1235		Revoked  bool                // true 表示该回执已被撤销（仅历史重放可能；重放不恢复回执）
1236	}
