1238	// ImportReceipts 按文件顺序整批应用回执记录。
1239	//
1240	// 逐条处理：与逐件 Receipt 共用同一回执请求号去重范围，同请求号且批次、包裹、
1241	// 结果、清理后的原因相同的记录返回首次结果与时间（重放），不检查当前状态、不追加
1242	// 轨迹、不改变批次进度；换内容报冲突。首次回执要求批次存在、包裹属于该批次、
1243	// 尚未在该批次回执且当前仍在该批次配送中（含本文件前面记录已产生的回执）。
1244	// 全部记录可接受时作为一个整体原子落盘；任一记录无效、冲突或受理条件不符，
1245	// 整份拒绝并提示记录位置，台账保持导入前状态，新请求号均不占用。
1246	// 全部为历史重放时不改写台账。
1247	func (s *Store) ImportReceipts(records []ReceiptImportRecord, now time.Time) ([]ReceiptImportItem, error) {
1248		// 在台账副本上按文件顺序试算：任一记录失败直接放弃副本，原台账保持不变。
1249		work, err := s.fork()
1250		if err != nil {
1251			return nil, err
1252		}
1253		items := make([]ReceiptImportItem, 0, len(records))
1254		hasNew := false
1255		for i, rec := range records {
1256			res, replayed, _, err := work.applyReceipt(rec.Request, rec.Batch, rec.Parcel, rec.Result, rec.Reason, now)
1257			if err != nil {
1258				return nil, fmt.Errorf("第 %d 条记录（请求号 %q）：%w", i+1, rec.Request, err)
1259			}
1260			if !replayed {
1261				hasNew = true
1262			}
1263			items = append(items, ReceiptImportItem{Record: rec, Time: res.Time, Replayed: replayed, Revoked: res.RevokedBy != ""})
1264		}
1265		if !hasNew {
1266			return items, nil // 全部为历史重放：不改写台账
1267		}
1268	
1269		// 整体提交：副本替换当前台账后一次原子落盘，失败时恢复导入前状态。
1270		orig := s.data
1271		s.data = work.data
1272		if err := s.save(); err != nil {
1273			s.data = orig
1274			return nil, err
1275		}
1276		return items, nil
1277	}
1278	
1279	// fork 返回当前台账的深拷贝副本，供整批导入试算；副本上的任何改动都不影响原台账。
1280	func (s *Store) fork() (*Store, error) {
1281		buf, err := json.Marshal(s.data)
1282		if err != nil {
1283			return nil, fmt.Errorf("准备回执整批导入失败: %w", err)
1284		}
1285		var cp ledgerFile
1286		if err := json.Unmarshal(buf, &cp); err != nil {
1287			return nil, fmt.Errorf("准备回执整批导入失败: %w", err)
1288		}
1289		return &Store{path: s.path, data: cp}, nil
1290	}
