1292	// RevokeReceipt 撤销一条误录的配送回执：经核实包裹实际仍由原配送员配送，
1293	// 撤销错误的签收或失败登记，不收回实物。包裹与批次取自原回执，不可另选。
1294	//
1295	// 首次撤销：原回执必须存在、未撤销且仍为该件在该批次的有效回执；所属批次
1296	// 未中止、未转交；原回执必须是该包裹最后一条轨迹（其后发生过流转、冻结或
1297	// 解除均拒绝，其他成员的后续操作不阻止撤销），包裹仍在原出发站且状态与回执
1298	// 结果一致。任一不满足则拒绝，不作任何改动。成功后该件恢复原批次配送中，
1299	// 站点、配送员不变，该回执不再计入有效回执（原本已完成的批次恢复配送中，
1300	// 原成员顺序与出站或接手时间保留，其他成员及回执不变）；原回执结果与轨迹
1301	// 永久保留并标记已撤销，追加一条撤销回执记录，回执请求号不删除也不释放。
1302	// 每件同批次最多一条未撤销回执，撤销后可用新回执请求号再次提交签收或失败，
1303	// 也可随原批次中止或续接。撤销不恢复配送前旧交接的退回资格。
1304	// 撤销请求号独立去重，可与其他业务编号同名：相同请求号且原回执、清理后的
1305	// 原因相同，直接返回首次撤销信息和时间，replayed 为 true，不检查现状、不
1306	// 再次改变进度或改写台账（后续重新回执、中止或续接后仍成立）；请求号相同
1307	// 但内容不同报冲突。每条原回执只能撤销一次，换撤销号再次撤销它拒绝；
1308	// 失败的首次撤销不占用请求号。
1309	func (s *Store) RevokeReceipt(request, receiptReq, reason string, now time.Time) (res *RevokeResult, replayed bool, err error) {
1310		if saved, ok := s.data.Revokes[request]; ok {
1311			if saved.Receipt == receiptReq && saved.Reason == reason {
1312				return saved, true, nil
1313			}
1314			return nil, false, fmt.Errorf("撤销请求号 %q 已用于一次不同的撤销（原回执=%q 原因=%q），内容冲突",
1315				request, saved.Receipt, saved.Reason)
1316		}
1317	
1318		rc, ok := s.data.Receipts[receiptReq]
1319		if !ok {
1320			return nil, false, fmt.Errorf("撤销失败：原回执请求号 %q 不存在", receiptReq)
1321		}
1322		if rc.RevokedBy != "" {
1323			return nil, false, fmt.Errorf("撤销失败：原回执 %q 已撤销（撤销请求号 %q），每条原回执只能撤销一次", receiptReq, rc.RevokedBy)
1324		}
1325		b := s.data.Batches[rc.Batch] // 回执所属批次必存在（载入校验保证）
1326		if b.AbortedBy != "" {
1327			return nil, false, fmt.Errorf("撤销失败：批次 %q 已中止（中止请求号 %q），不能撤销其中的回执", rc.Batch, b.AbortedBy)
1328		}
1329		if b.TransferredBy != "" {
1330			return nil, false, fmt.Errorf("撤销失败：批次 %q 已转交（续接请求号 %q），不能撤销其中的回执", rc.Batch, b.TransferredBy)
1331		}
1332		entry := b.Receipts[rc.Parcel]
1333		if entry == nil || entry.Request != receiptReq {
1334			return nil, false, fmt.Errorf("撤销失败：回执 %q 已不是包裹 %q 在批次 %q 的有效回执", receiptReq, rc.Parcel, rc.Batch)
1335		}
1336		p := s.data.Parcels[rc.Parcel] // 批次成员必已登记（载入校验保证）
1337		last := p.Trail[len(p.Trail)-1]
1338		if last.Op != "回执" || last.Request != receiptReq {
1339			return nil, false, fmt.Errorf("撤销失败：包裹 %q 在原回执 %q 之后又发生流转、冻结或解除，不能撤销该回执", rc.Parcel, receiptReq)
1340		}
1341		if p.Station != b.Station {
1342			return nil, false, fmt.Errorf("撤销失败：包裹 %q 当前归属 %q，不在原出发站 %q，不能撤销该回执", rc.Parcel, p.Station, b.Station)
1343		}
1344		want := statusSigned
1345		if rc.Result == resultFailed {
1346			want = statusInStation
1347		}
1348		if p.Status != want {
1349			return nil, false, fmt.Errorf("撤销失败：包裹 %q 当前状态为 %q，与原回执 %q 的结果 %q 不一致，不能撤销",
1350				rc.Parcel, p.Status, receiptReq, rc.Result)
1351		}
1352	
1353		res = &RevokeResult{
1354			Request: request,
1355			Receipt: receiptReq,
1356			Batch:   rc.Batch,
1357			Parcel:  rc.Parcel,
1358			Reason:  reason,
1359			Time:    now,
1360		}
1361		s.data.Revokes[request] = res
1362		rc.RevokedBy = request
1363		entry.RevokedBy = request
1364	
1365		// 记录旧值，落盘失败时整体回滚。
1366		oldStatus := p.Status
1367		oldTrailLen := len(p.Trail)
1368		p.Status = statusDelivering // 恢复原批次配送中，站点与配送员不变
1369		p.Trail = append(p.Trail, Event{
1370			Op:         "撤销回执",
1371			Station:    b.Station,
1372			Batch:      rc.Batch,
1373			Request:    request,
1374			RefRequest: receiptReq,
1375			Reason:     reason,
1376			Time:       now,
1377		})
1378	
1379		if err := s.save(); err != nil {
1380			delete(s.data.Revokes, request)
1381			rc.RevokedBy = ""
1382			entry.RevokedBy = ""
1383			p.Status = oldStatus
1384			p.Trail = p.Trail[:oldTrailLen]
1385			return nil, false, err
1386		}
1387		return res, false, nil
1388	}
