1400	// BatchRevokes 返回一个配送批次相关的全部撤销记录，按撤销时间升序。
1401	func (s *Store) BatchRevokes(batch string) []*RevokeResult {
1402		var out []*RevokeResult
1403		for _, rv := range s.data.Revokes {
1404			if rv.Batch == batch {
1405				out = append(out, rv)
1406			}
1407		}
1408		sort.Slice(out, func(i, j int) bool { return out[i].Time.Before(out[j].Time) })
1409		return out
1410	}
