1412	// Freeze 对一件在站包裹登记异常冻结。
1413	//
1414	// 首次冻结：包裹必须已登记、当前归属指定站点且状态为在站；配送中、已签收或已冻结的
1415	// 包裹不能冻结。成功后站点不变，状态转为异常冻结，追加一条含异常单号、原因、站点和
1416	// 时间的冻结记录。一件包裹同时只能有一张未解除异常单。
1417	// 冻结只是管理记录，不移动实物、不算新流转。
1418	// 异常单号标识一次异常，解除后也不能复用：相同异常单号且包裹、站点、清理后的原因
1419	// 相同，直接返回首次冻结结果与时间，replayed 为 true，不再次冻结（即使该异常单已解除、
1420	// 包裹已发生新的流转，也不检查当前状态）；异常单号相同但内容不同报冲突；
1421	// 失败的首次冻结不占用异常单号。异常单号与包裹编号及其他业务编号分属独立去重范围。
1422	func (s *Store) Freeze(incident, parcel, station, reason string, now time.Time) (res *FreezeResult, replayed bool, err error) {
1423		if saved, ok := s.data.Freezes[incident]; ok {
1424			if saved.Parcel == parcel && saved.Station == station && saved.Reason == reason {
1425				return saved, true, nil
1426			}
1427			return nil, false, fmt.Errorf("异常单号 %q 已用于一次不同的冻结（包裹=%q 站点=%q 原因=%q），内容冲突",
1428				incident, saved.Parcel, saved.Station, saved.Reason)
1429		}
1430	
1431		p, ok := s.data.Parcels[parcel]
1432		if !ok {
1433			return nil, false, fmt.Errorf("冻结失败：包裹 %q 未登记，冻结未执行", parcel)
1434		}
1435		if p.Station != station {
1436			return nil, false, fmt.Errorf("冻结失败：包裹 %q 当前归属 %q，不在指定站点 %q，冻结未执行", parcel, p.Station, station)
1437		}
1438		if p.Status != statusInStation {
1439			return nil, false, fmt.Errorf("冻结失败：包裹 %q 当前状态为 %q，仅在站包裹可以冻结，冻结未执行", parcel, p.Status)
1440		}
1441	
1442		res = &FreezeResult{
1443			Incident: incident,
1444			Parcel:   parcel,
1445			Station:  station,
1446			Reason:   reason,
1447			Time:     now,
1448		}
1449		s.data.Freezes[incident] = res
1450	
1451		// 记录旧值，落盘失败时整体回滚。
1452		oldStatus := p.Status
1453		oldTrail := append([]Event(nil), p.Trail...)
1454		p.Status = statusFrozen // 站点不变
1455		p.Trail = append(p.Trail, Event{
1456			Op:       "冻结",
1457			Station:  station,
1458			Incident: incident,
1459			Reason:   reason,
1460			Time:     now,
1461		})
1462	
1463		if err := s.save(); err != nil {
1464			delete(s.data.Freezes, incident)
1465			p.Status, p.Trail = oldStatus, oldTrail
1466			return nil, false, err
1467		}
1468		return res, false, nil
1469	}
