1471	// Unfreeze 解除一件包裹当前的异常冻结。
1472	//
1473	// 首次解除：异常单必须存在且尚未解除，并且仍是该包裹当前冻结对应的异常单；
1474	// 异常单不存在、已解除或对应关系不符均拒绝。成功后包裹在原站恢复在站，原异常单
1475	// 永久标记为已解除（异常单号不得复用），追加一条含异常单号、解除请求号、处理说明及
1476	// 时间的解除记录，原冻结记录不删改；之后可用新异常单再次冻结。
1477	// 解除只是管理记录，不移动实物、不算新流转。
1478	// 解除请求号独立去重，可与异常单号、包裹号及其他业务编号同名：相同解除请求号且异常单、
1479	// 处理说明相同，直接返回首次解除结果与时间，replayed 为 true，不检查当前状态，也不影响
1480	// 后来新建的异常单或后续流转；请求号相同但内容不同报冲突；失败的首次解除不占用请求号。
1481	func (s *Store) Unfreeze(request, incident, note string, now time.Time) (res *UnfreezeResult, replayed bool, err error) {
1482		if saved, ok := s.data.Unfreezes[request]; ok {
1483			if saved.Incident == incident && saved.Note == note {
1484				return saved, true, nil
1485			}
1486			return nil, false, fmt.Errorf("解除请求号 %q 已用于一次不同的解除（异常单=%q 处理说明=%q），内容冲突",
1487				request, saved.Incident, saved.Note)
1488		}
1489	
1490		f, ok := s.data.Freezes[incident]
1491		if !ok {
1492			return nil, false, fmt.Errorf("解除失败：异常单号 %q 不存在，解除未执行", incident)
1493		}
1494		if f.ReleasedBy != "" {
1495			return nil, false, fmt.Errorf("解除失败：异常单 %q 已解除（解除请求号 %q），不能重复解除", incident, f.ReleasedBy)
1496		}
1497		p, ok := s.data.Parcels[f.Parcel]
1498		if !ok {
1499			return nil, false, fmt.Errorf("解除失败：异常单 %q 对应的包裹 %q 不存在，解除未执行", incident, f.Parcel)
1500		}
1501		if p.Status != statusFrozen || activeFreeze(p) != incident {
1502			return nil, false, fmt.Errorf("解除失败：异常单 %q 不是包裹 %q 当前冻结对应的异常单（当前异常单 %q），解除未执行",
1503				incident, f.Parcel, activeFreeze(p))
1504		}
1505	
1506		res = &UnfreezeResult{
1507			Request:  request,
1508			Incident: incident,
1509			Parcel:   f.Parcel,
1510			Note:     note,
1511			Time:     now,
1512		}
1513		s.data.Unfreezes[request] = res
1514		f.ReleasedBy = request
1515	
1516		// 记录旧值，落盘失败时整体回滚。
1517		oldStatus := p.Status
1518		oldTrail := append([]Event(nil), p.Trail...)
1519		p.Status = statusInStation // 在原站恢复在站，站点不变
1520		p.Trail = append(p.Trail, Event{
1521			Op:       "解除冻结",
1522			Station:  f.Station,
1523			Incident: incident,
1524			Request:  request,
1525			Note:     note,
1526			Time:     now,
1527		})
1528	
1529		if err := s.save(); err != nil {
1530			delete(s.data.Unfreezes, request)
1531			f.ReleasedBy = ""
1532			p.Status, p.Trail = oldStatus, oldTrail
1533			return nil, false, err
1534		}
1535		return res, false, nil
1536	}
