1538	// Abort 中止一个配送批次：配送员已将该批次全部尚未回执的包裹实物收回出发站。
1539	// 成员与站点取自原批次结果，不允许另选成员或站点。
1540	//
1541	// 首次中止：批次必须存在、尚未完成且未中止，且至少有一件未回执成员；这些成员
1542	// 必须仍在原批次配送中、归属出发站，任一不符整批拒绝、不作任何改动。已回执成员
1543	// 及其回执完全保留，即使它们已进入其他批次或被冻结也不阻止中止，不检查也不改变
1544	// 其当前状态。全部满足时按原成员顺序将全部未回执件恢复“在站”（站点为出发站），
1545	// 各追加一条含批次、中止请求号、原因、站点和时间的收回记录；收回不是失败回执，
1546	// 批次回执记录不变。中止永久关闭原批次，原成员顺序、配送员与出站时间保留不变。
1547	// 收回算新的流转，收回后不能退回出站前的旧交接；收回件可交接、冻结或再次出站，
1548	// 但不能首次回执旧批次（receipt 与 receipt-import 同样遵守）。
1549	// 中止请求号独立去重，可与批次号、包裹号及其他业务编号同名：相同请求号且批次、
1550	// 清理后的原因相同，直接返回首次收回集合与时间，replayed 为 true，不重新计算成员、
1551	// 不检查当前状态、不改写台账；请求号相同但批次或原因不同报冲突。
1552	// 每批只能成功中止一次：换请求号再中止或中止已正常完成的批次均拒绝；
1553	// 失败的首次中止不占用请求号。
1554	func (s *Store) Abort(request, batch, reason string, now time.Time) (res *AbortResult, replayed bool, err error) {
1555		if saved, ok := s.data.Aborts[request]; ok {
1556			if saved.Batch == batch && saved.Reason == reason {
1557				return saved, true, nil
1558			}
1559			return nil, false, fmt.Errorf("中止请求号 %q 已用于一次不同的中止（批次=%q 原因=%q），内容冲突",
1560				request, saved.Batch, saved.Reason)
1561		}
1562	
1563		b, ok := s.data.Batches[batch]
1564		if !ok {
1565			return nil, false, fmt.Errorf("中止失败：批次号 %q 不存在", batch)
1566		}
1567		if b.AbortedBy != "" {
1568			return nil, false, fmt.Errorf("中止失败：批次 %q 已中止（中止请求号 %q），每批只能成功中止一次", batch, b.AbortedBy)
1569		}
1570		if b.TransferredBy != "" {
1571			return nil, false, fmt.Errorf("中止失败：批次 %q 已转交（续接请求号 %q），不能中止", batch, b.TransferredBy)
1572		}
1573		if b.Done() {
1574			return nil, false, fmt.Errorf("中止失败：批次 %q 已全部回执完成，不能中止", batch)
1575		}
1576	
1577		// 按原成员顺序挑出全部未回执成员（批次未完成，必至少有一件）。
1578		recalled := make([]string, 0, len(b.Parcels)-len(b.Receipts))
1579		for _, pid := range b.Parcels {
1580			if e, done := b.Receipts[pid]; !done || e.RevokedBy != "" {
1581				recalled = append(recalled, pid)
1582			}
1583		}
1584		if len(recalled) == 0 {
1585			return nil, false, fmt.Errorf("中止失败：批次 %q 没有未回执成员，不能中止", batch)
1586		}
1587	
1588		// 先做全部校验：未回执成员必须仍在原批次配送中且归属出发站，任一不符整批拒绝。
1589		for _, pid := range recalled {
1590			p := s.data.Parcels[pid] // 批次成员必已登记（载入校验保证）
1591			if p.Status != statusDelivering || currentBatch(p) != batch || p.Station != b.Station {
1592				return nil, false, fmt.Errorf("中止失败：包裹 %q 当前归属 %q、状态 %q，不在批次 %q 从出发站 %q 配送中，整批中止未执行",
1593					pid, p.Station, p.Status, batch, b.Station)
1594			}
1595		}
1596	
1597		res = &AbortResult{
1598			Request: request,
1599			Batch:   batch,
1600			Station: b.Station,
1601			Reason:  reason,
1602			Parcels: recalled,
1603			Time:    now,
1604		}
1605		s.data.Aborts[request] = res
1606		b.AbortedBy = request
1607	
1608		// 记录旧值，落盘失败时整体回滚。
1609		prev := make(map[string]struct {
1610			status string
1611			trail  []Event
1612		}, len(recalled))
1613		for _, pid := range recalled {
1614			p := s.data.Parcels[pid]
1615			prev[pid] = struct {
1616				status string
1617				trail  []Event
1618			}{p.Status, append([]Event(nil), p.Trail...)}
1619			p.Status = statusInStation // 实物已收回出发站，站点仍记出发站
1620			p.Trail = append(p.Trail, Event{
1621				Op:      "收回",
1622				Station: b.Station,
1623				Batch:   batch,
1624				Request: request,
1625				Reason:  reason,
1626				Time:    now,
1627			})
1628		}
1629	
1630		if err := s.save(); err != nil {
1631			delete(s.data.Aborts, request)
1632			b.AbortedBy = ""
1633			for pid, old := range prev {
1634				p := s.data.Parcels[pid]
1635				p.Status = old.status
1636				p.Trail = old.trail
1637			}
1638			return nil, false, err
1639		}
1640		return res, false, nil
1641	}
