1643	// BatchAbort 返回一个配送批次的中止结果；批次不存在或未中止时返回 nil。
1644	func (s *Store) BatchAbort(batch string) *AbortResult {
1645		b, ok := s.data.Batches[batch]
1646		if !ok || b.AbortedBy == "" {
1647			return nil
1648		}
1649		return s.data.Aborts[b.AbortedBy]
1650	}
