1652	// Transfer 把原批次全部尚未回执的包裹在配送途中整批交给另一配送员：
1653	// 新建批次继续配送，无需回站。成员与站点取自原批次，不允许另选成员或站点。
1654	//
1655	// 首次续接：原批次必须存在、仍开放（未中止、未转交）且有未回执成员；新批次号
1656	// 必须从未被出站或续接使用；新配送员必须与原配送员不同。未回执成员必须全部仍在
1657	// 原批次配送中且归属出发站，任一不符整批拒绝、不作任何改动。已回执成员不检查也
1658	// 不变更，其后续流转或冻结不阻止续接。全部满足时新批次按原成员顺序接纳全部未
1659	// 回执件，沿用出发站，记录新配送员及接手时间；包裹保持“配送中”及原站点，当前
1660	// 配送归属切换到新批次，各追加一条含请求号、前后批次、新配送员、站点、原因和
1661	// 时间的续接记录。原批次永久关闭为“已转交”，原成员、配送员、出站时间与真实
1662	// 回执保留不变；转交不算回执、收回或再次出站。续接算新的流转，续接后不能退回
1663	// 配送前的旧交接。
1664	// 续接请求号独立去重，可与批次号、包裹号及其他业务编号同名：相同请求号且原批次、
1665	// 新批次、新配送员、清理后的原因相同，直接返回首次转交集合、续接信息及时间，
1666	// replayed 为 true，不检查现状、不重算成员、不改写台账；请求号相同但内容不同报
1667	// 冲突；失败的首次续接不占用请求号。
1668	func (s *Store) Transfer(request, fromBatch, toBatch, courier, reason string, now time.Time) (res *TransferResult, replayed bool, err error) {
1669		if saved, ok := s.data.Transfers[request]; ok {
1670			if saved.FromBatch == fromBatch && saved.ToBatch == toBatch && saved.ToCourier == courier && saved.Reason == reason {
1671				return saved, true, nil
1672			}
1673			return nil, false, fmt.Errorf("续接请求号 %q 已用于一次不同的续接（原批次=%q 新批次=%q 新配送员=%q），内容冲突",
1674				request, saved.FromBatch, saved.ToBatch, saved.ToCourier)
1675		}
1676	
1677		b, ok := s.data.Batches[fromBatch]
1678		if !ok {
1679			return nil, false, fmt.Errorf("续接失败：原批次号 %q 不存在", fromBatch)
1680		}
1681		if b.AbortedBy != "" {
1682			return nil, false, fmt.Errorf("续接失败：批次 %q 已中止（中止请求号 %q），不能续接", fromBatch, b.AbortedBy)
1683		}
1684		if b.TransferredBy != "" {
1685			return nil, false, fmt.Errorf("续接失败：批次 %q 已转交（续接请求号 %q），不能再次续接", fromBatch, b.TransferredBy)
1686		}
1687		if _, used := s.data.Batches[toBatch]; used {
1688			return nil, false, fmt.Errorf("续接失败：新批次号 %q 已被出站或续接使用，不能复用", toBatch)
1689		}
1690		if courier == b.Courier {
1691			return nil, false, fmt.Errorf("续接失败：新配送员 %q 不能与原批次 %q 的配送员相同", courier, fromBatch)
1692		}
1693	
1694		// 按原成员顺序挑出全部未回执成员（批次仍开放，必至少有一件）。
1695		moved := make([]string, 0, len(b.Parcels)-len(b.Receipts))
1696		for _, pid := range b.Parcels {
1697			if e, done := b.Receipts[pid]; !done || e.RevokedBy != "" {
1698				moved = append(moved, pid)
1699			}
1700		}
1701		if len(moved) == 0 {
1702			return nil, false, fmt.Errorf("续接失败：批次 %q 没有未回执成员，不能续接", fromBatch)
1703		}
1704	
1705		// 先做全部校验：未回执成员必须仍在原批次配送中且归属出发站，任一不符整批拒绝。
1706		for _, pid := range moved {
1707			p := s.data.Parcels[pid] // 批次成员必已登记（载入校验保证）
1708			if p.Status != statusDelivering || currentBatch(p) != fromBatch || p.Station != b.Station {
1709				return nil, false, fmt.Errorf("续接失败：包裹 %q 当前归属 %q、状态 %q，不在批次 %q 从出发站 %q 配送中，整批续接未执行",
1710					pid, p.Station, p.Status, fromBatch, b.Station)
1711			}
1712		}
1713	
1714		res = &TransferResult{
1715			Request:     request,
1716			FromBatch:   fromBatch,
1717			ToBatch:     toBatch,
1718			Station:     b.Station,
1719			FromCourier: b.Courier,
1720			ToCourier:   courier,
1721			Reason:      reason,
1722			Parcels:     append([]string(nil), moved...),
1723			Time:        now,
1724		}
1725		s.data.Transfers[request] = res
1726		s.data.Batches[toBatch] = &BatchResult{
1727			Batch:        toBatch,
1728			Station:      b.Station,
1729			Courier:      courier,
1730			Parcels:      append([]string(nil), moved...),
1731			Time:         now,
1732			Receipts:     map[string]*ReceiptEntry{},
1733			RelayedFrom:  fromBatch,
1734			RelayRequest: request,
1735		}
1736		b.TransferredBy = request
1737	
1738		// 记录旧值，落盘失败时整体回滚。包裹保持“配送中”及原站点，只追加续接轨迹。
1739		prev := make(map[string][]Event, len(moved))
1740		for _, pid := range moved {
1741			p := s.data.Parcels[pid]
1742			prev[pid] = append([]Event(nil), p.Trail...)
1743			p.Trail = append(p.Trail, Event{
1744				Op:        "续接",
1745				Station:   b.Station,
1746				Batch:     toBatch,
1747				FromBatch: fromBatch,
1748				Courier:   courier,
1749				Request:   request,
1750				Reason:    reason,
1751				Time:      now,
1752			})
1753		}
1754	
1755		if err := s.save(); err != nil {
1756			delete(s.data.Transfers, request)
1757			delete(s.data.Batches, toBatch)
1758			b.TransferredBy = ""
1759			for pid, old := range prev {
1760				s.data.Parcels[pid].Trail = old
1761			}
1762			return nil, false, err
1763		}
1764		return res, false, nil
1765	}
