1781	// currentBatch 返回包裹当前配送归属的批次号（最后一条出站或续接记录的批次）；
1782	// 不在配送中返回空。续接不新增出站记录，但会把当前配送归属切换到新批次。
1783	func currentBatch(p *Parcel) string {
1784		for i := len(p.Trail) - 1; i >= 0; i-- {
1785			if p.Trail[i].Op == "出站" || p.Trail[i].Op == "续接" {
1786				return p.Trail[i].Batch
1787			}
1788		}
1789		return ""
1790	}
1791	
1792	// activeFreeze 返回包裹当前未解除冻结对应的异常单号；未冻结返回空。
1793	// 冻结状态与轨迹成对追加，故当前状态为异常冻结时最后一条冻结记录即为当前异常单。
1794	func activeFreeze(p *Parcel) string {
1795		if p.Status != statusFrozen {
1796			return ""
1797		}
1798		for i := len(p.Trail) - 1; i >= 0; i-- {
1799			if p.Trail[i].Op == "冻结" {
1800				return p.Trail[i].Incident
1801			}
1802		}
1803		return ""
1804	}
1805	
1806	// lastFlowEvent 返回轨迹中最后一条真实流转记录（交接/退回/出站/回执/收回）。
1807	// 冻结与解除只是管理记录，不算新流转，判定旧交接可否退回时须跳过它们。
1808	func lastFlowEvent(trail []Event) Event {
1809		for i := len(trail) - 1; i >= 0; i-- {
1810			switch trail[i].Op {
1811			case "冻结", "解除冻结":
1812				continue
1813			default:
1814				return trail[i]
1815			}
1816		}
1817		return Event{}
1818	}
