1829	// sameOrder 判断两个列表长度与逐元素顺序完全一致。
1830	func sameOrder(a, b []string) bool {
1831		if len(a) != len(b) {
1832			return false
1833		}
1834		for i := range a {
1835			if a[i] != b[i] {
1836				return false
1837			}
1838		}
1839		return true
1840	}
1841	
1842	// sameSet 判断两个包裹列表作为集合是否相同（顺序不影响判定）。
1843	func sameSet(a, b []string) bool {
1844		if len(a) != len(b) {
1845			return false
1846		}
1847		x := append([]string(nil), a...)
1848		y := append([]string(nil), b...)
1849		sort.Strings(x)
1850		sort.Strings(y)
1851		for i := range x {
1852			if x[i] != y[i] {
1853				return false
1854			}
1855		}
1856		return true
1857	}
