1859	// save 将当前台账作为一个整体原子写入数据文件：先写临时文件并同步，
1860	// 校验可重新解析后再原子替换，最后目录同步，避免保存失败留下部分业务变更。
1861	func (s *Store) save() error {
1862		if err := os.MkdirAll(filepath.Dir(s.path), 0o755); err != nil {
1863			return fmt.Errorf("保存数据文件失败: %w", err)
1864		}
1865		buf, err := json.MarshalIndent(s.data, "", "  ")
1866		if err != nil {
1867			return fmt.Errorf("保存数据文件失败: %w", err)
1868		}
1869		buf = append(buf, '\n')
1870	
1871		tmp, err := os.CreateTemp(filepath.Dir(s.path), ".parcelhub-*.tmp")
1872		if err != nil {
1873			return fmt.Errorf("保存数据文件失败: %w", err)
1874		}
1875		tmpName := tmp.Name()
1876		cleanup := func() { _ = os.Remove(tmpName) }
1877	
1878		if _, err := tmp.Write(buf); err != nil {
1879			_ = tmp.Close()
1880			cleanup()
1881			return fmt.Errorf("保存数据文件失败: %w", err)
1882		}
1883		if err := tmp.Sync(); err != nil {
1884			_ = tmp.Close()
1885			cleanup()
1886			return fmt.Errorf("保存数据文件失败: %w", err)
1887		}
1888		if err := tmp.Close(); err != nil {
1889			cleanup()
1890			return fmt.Errorf("保存数据文件失败: %w", err)
1891		}
1892	
1893		// 替换前确认临时文件自身可解析，杜绝把损坏内容写到正式位置。
1894		var check ledgerFile
1895		if err := json.Unmarshal(buf, &check); err != nil {
1896			cleanup()
1897			return fmt.Errorf("保存数据文件失败: 写入内容无效: %w", err)
1898		}
1899	
1900		if err := os.Rename(tmpName, s.path); err != nil {
1901			cleanup()
1902			return fmt.Errorf("保存数据文件失败: %w", err)
1903		}
1904		if dir, err := os.Open(filepath.Dir(s.path)); err == nil {
1905			_ = dir.Sync()
1906			_ = dir.Close()
1907		}
1908		return nil
1909	}
1910

