143			case "撤销回执":
144				fmt.Fprintf(stdout, "  %d. 操作: 撤销回执    站点: %s    批次号: %s    撤销请求号: %s    原回执请求号: %s    原因: %s    时间: %s\n",
145					i+1, e.Station, e.Batch, e.Request, e.RefRequest, e.Reason, e.Time.Format(timeFmt))
146			case "冻结":
147				fmt.Fprintf(stdout, "  %d. 操作: 冻结    站点: %s    异常单号: %s    原因: %s    时间: %s\n",
148					i+1, e.Station, e.Incident, e.Reason, e.Time.Format(timeFmt))
149			case "解除冻结":
150				fmt.Fprintf(stdout, "  %d. 操作: 解除冻结    站点: %s    异常单号: %s    解除请求号: %s    处理说明: %s    时间: %s\n",
151					i+1, e.Station, e.Incident, e.Request, e.Note, e.Time.Format(timeFmt))
152			case "收回":
153				fmt.Fprintf(stdout, "  %d. 操作: 收回    站点: %s    批次号: %s    中止请求号: %s    原因: %s    时间: %s\n",
154					i+1, e.Station, e.Batch, e.Request, e.Reason, e.Time.Format(timeFmt))
155			case "续接":
156				fmt.Fprintf(stdout, "  %d. 操作: 续接    站点: %s    原批次号: %s    新批次号: %s    新配送员: %s    续接请求号: %s    原因: %s    时间: %s\n",
157					i+1, e.Station, e.FromBatch, e.Batch, e.Courier, e.Request, e.Reason, e.Time.Format(timeFmt))
158			default:
159				req := e.Request
160				if req == "" {
161					req = "-"
162				}
163				fmt.Fprintf(stdout, "  %d. 操作: %s    站点: %s    请求号: %s    时间: %s\n",
164					i+1, e.Op, e.Station, req, e.Time.Format(timeFmt))
165			}
166		}
167		return exitOK
168	}
