454	// receiptFileRecord 是回执整批导入文件中的单条记录（JSON）。
455	type receiptFileRecord struct {
456		Request string `json:"request"`
457		Batch   string `json:"batch"`
458		Parcel  string `json:"parcel"`
459		Result  string `json:"result"`
460		Reason  string `json:"reason"`
461	}
462	
463	// loadReceiptImportFile 读取并解析回执整批导入文件。文件为有序且非空的
464	// JSON 数组，元素为 request/batch/parcel/result/reason 字段的对象；
465	// 文件只读，绝不改写。任一记录清洗后不合法或请求号在文件内重复，
466	// 都返回带记录位置的错误，整份不予导入。
467	func loadReceiptImportFile(path string) ([]ReceiptImportRecord, error) {
468		raw, err := os.ReadFile(path)
469		if err != nil {
470			return nil, fmt.Errorf("读取回执导入文件失败: %w", err)
471		}
472		dec := json.NewDecoder(bytes.NewReader(raw))
473		dec.DisallowUnknownFields()
474		var records []receiptFileRecord
475		if err := dec.Decode(&records); err != nil {
476			return nil, fmt.Errorf("解析回执导入文件失败: %w", err)
477		}
478		var extra any
479		if err := dec.Decode(&extra); err != io.EOF {
480			return nil, fmt.Errorf("解析回执导入文件失败: 回执列表之后存在多余内容")
481		}
482		if len(records) == 0 {
483			return nil, fmt.Errorf("回执导入文件必须是有序且非空的回执列表")
484		}
485	
486		clean := make([]ReceiptImportRecord, 0, len(records))
487		seen := make(map[string]bool, len(records))
488		for i, rawRec := range records {
489			rec, err := cleanReceiptImportRecord(rawRec)
490			if err != nil {
491				return nil, fmt.Errorf("第 %d 条记录: %w", i+1, err)
492			}
493			if seen[rec.Request] {
494				return nil, fmt.Errorf("第 %d 条记录: 回执请求号 %q 在文件内重复", i+1, rec.Request)
495			}
496			seen[rec.Request] = true
497			clean = append(clean, rec)
498		}
499		return clean, nil
500	}
501	
502	// cleanReceiptImportRecord 清洗并校验一条导入记录：各标识去除两端空白后不可为空；
503	// 结果为失败时必须给出清理后非空的原因，签收时不可带原因。
504	func cleanReceiptImportRecord(raw receiptFileRecord) (ReceiptImportRecord, error) {
505		var rec ReceiptImportRecord
506		var err error
507		if rec.Request, err = cleanID("回执请求号", raw.Request); err != nil {
508			return rec, err
509		}
510		if rec.Batch, err = cleanID("批次号", raw.Batch); err != nil {
511			return rec, err
512		}
513		if rec.Parcel, err = cleanID("包裹编号", raw.Parcel); err != nil {
514			return rec, err
515		}
516		if rec.Result, err = cleanID("回执结果", raw.Result); err != nil {
517			return rec, err
518		}
519		if rec.Result != resultSigned && rec.Result != resultFailed {
520			return rec, fmt.Errorf("回执结果只能是 %q 或 %q，得到 %q", resultSigned, resultFailed, rec.Result)
521		}
522		rec.Reason = strings.TrimSpace(raw.Reason)
523		if rec.Result == resultFailed && rec.Reason == "" {
524			return rec, fmt.Errorf("结果为失败时原因不可为空或仅含空白")
525		}
526		if rec.Result == resultSigned && rec.Reason != "" {
527			return rec, fmt.Errorf("结果为签收时不可带原因")
528		}
529		return rec, nil
530	}
