532	func cmdReceiptImport(dataFile string, argv []string, stdout, stderr io.Writer) int {
533		fs := newFlagSet("receipt-import", stderr)
534		fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
535		file := fs.String("file", "", "回执导入文件路径（JSON 数组，只读，不会被修改）")
536		if ok, code := parseFlags(fs, argv, stdout, stderr, printReceiptImportHelp); !ok {
537			return code
538		}
539	
540		if strings.TrimSpace(*file) == "" {
541			fmt.Fprintf(stderr, "%s receipt-import: 选项 --file 需要一个非空的回执导入文件路径\n", appName)
542			return exitBusiness
543		}
544	
545		// 输入文件只读；读取、解析或清洗失败时整份不予导入。
546		records, err := loadReceiptImportFile(*file)
547		if err != nil {
548			fmt.Fprintf(stderr, "%s receipt-import: %v\n", appName, err)
549			return exitBusiness
550		}
551	
552		store, release, err := OpenForUpdate(dataFile)
553		if err != nil {
554			fmt.Fprintf(stderr, "%s receipt-import: %v\n", appName, err)
555			return exitBusiness
556		}
557		defer release()
558		items, err := store.ImportReceipts(records, now())
559		if err != nil {
560			fmt.Fprintf(stderr, "%s receipt-import: %v\n", appName, err)
561			return exitBusiness
562		}
563	
564		replayed := 0
565		for _, it := range items {
566			if it.Replayed {
567				replayed++
568			}
569		}
570		fmt.Fprintf(stdout, "回执导入成功（共 %d 条：新增 %d 条，重放 %d 条）\n", len(items), len(items)-replayed, replayed)
571		for i, it := range items {
572			mark := "新增"
573			if it.Replayed {
574				mark = "重放（返回首次保存的结果）"
575			}
576			if it.Revoked {
577				mark += "，该回执已撤销"
578			}
579			line := fmt.Sprintf("  %d. 请求号: %s    批次号: %s    包裹编号: %s    结果: %s",
580				i+1, it.Record.Request, it.Record.Batch, it.Record.Parcel, it.Record.Result)
581			if it.Record.Result == resultFailed {
582				line += fmt.Sprintf("    原因: %s", it.Record.Reason)
583			}
584			fmt.Fprintf(stdout, "%s    标记: %s    时间: %s\n", line, mark, it.Time.Format(timeFmt))
585		}
586		return exitOK
587	}
