681			fmt.Fprintf(stdout, "批次来源: 续接自批次 %s（原配送员: %s，续接请求号: %s）\n",
682				b.RelayedFrom, src.FromCourier, b.RelayRequest)
683		}
684		if ab != nil {
685			fmt.Fprintf(stdout, "中止请求号: %s\n中止原因: %s\n中止时间: %s\n",
686				ab.Request, ab.Reason, ab.Time.Format(timeFmt))
