690				tr.ToBatch, tr.ToCourier, tr.Request, tr.Reason, tr.Time.Format(timeFmt))
691		}
692		fmt.Fprintf(stdout, "逐件回执（%d/%d 已回执）:\n", b.Effective(), len(b.Parcels))
693		for _, pid := range b.Parcels {
694			e, ok := b.Receipts[pid]
695			if !ok || e.RevokedBy != "" {
696				switch {
697				case tr != nil:
698					fmt.Fprintf(stdout, "  - %s    已转交    去向批次: %s    续接请求号: %s    时间: %s\n",
699						pid, tr.ToBatch, tr.Request, tr.Time.Format(timeFmt))
