702						pid, ab.Request, ab.Reason, ab.Time.Format(timeFmt))
703				case ok:
704					fmt.Fprintf(stdout, "  - %s    未回执（原回执 %s 已撤销，撤销请求号: %s）\n", pid, e.Request, e.RevokedBy)
705				default:
706					fmt.Fprintf(stdout, "  - %s    未回执\n", pid)
707				}
708				continue
709			}
710			if e.Result == resultFailed {
711				fmt.Fprintf(stdout, "  - %s    已回执    结果: %s    原因: %s    请求号: %s    时间: %s\n",
712					pid, e.Result, e.Reason, e.Request, e.Time.Format(timeFmt))
713			} else {
714				fmt.Fprintf(stdout, "  - %s    已回执    结果: %s    请求号: %s    时间: %s\n",
715					pid, e.Result, e.Request, e.Time.Format(timeFmt))
716			}
717		}
718		if rvs := store.BatchRevokes(cleanIDVal); len(rvs) > 0 {
719			fmt.Fprintf(stdout, "撤销记录（%d 条）:\n", len(rvs))
